/* Branded, non-blocking notice. Replaces alert(), which on iOS steals focus,
   halts the page and looks nothing like the rest of the product. Mirrors the
   toast in gym-app.js so coach and member speak the same visual language. */
function myToast(msg){
  var t=document.getElementById('myToast');
  if(!t){
    t=document.createElement('div');
    t.id='myToast'; t.className='mytoast';
    document.body.appendChild(t);
  }
  t.textContent=String(msg==null?'':msg);
  t.classList.add('open');
  clearTimeout(myToast._t);
  myToast._t=setTimeout(function(){ t.classList.remove('open'); },4200);
}
