function rawYoutubePlaybackTime(){try{return Math.max(0,Number(youtubePlayer&&youtubePlayer.getCurrentTime&&youtubePlayer.getCurrentTime())||0)}catch(e){return 0}}
function youtubePlaybackRate(){var rate=1;try{rate=Number(youtubePlayer&&youtubePlayer.getPlaybackRate&&youtubePlayer.getPlaybackRate())||1}catch(e){}return Math.max(.25,Math.min(4,rate))}
