    html=rows.map(function(track,index){var active=musicCurrentTrack&&musicCurrentTrack.id===track.id;return'<article class="studio-track" data-current="'+(active?'1':'0')+'">'+musicCoverHTML(track,false)+'<button class="studio-track__main" data-a="music-track" data-id="'+track.id+'" data-playlist="'+h(playlist||'')+'"><b>'+h(track.title)+'</b><span>'+h(track.artist||track.album||'Private upload')+'</span></button><button class="studio-track__more" data-a="music-track-more" data-id="'+track.id+'" aria-label="Track options">•••</button></article>'}).join('');
