function mmwEngine(){return window.MahfittMMW||null}
function mmwMonth(){var e=mmwEngine();return MMW.month||(e&&e.currentMonth?e.currentMonth(new Date()):new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'))}
function mmwLaunchCard(){var e=mmwEngine(),month=e&&e.monthLabel?e.monthLabel(mmwMonth()):'This month';return'<button class="mmw-launch" data-a="music-mmw-open" aria-label="Open MAHFITT Month Wrapped for '+h(month)+'"><span class="mmw-launch__mark" aria-hidden="true"><i></i><i></i><i></i></span><span class="mmw-launch__copy"><small>MAHFITT MONTH WRAPPED</small><b>'+h(month)+'</b><em>Your listening + training atmosphere, privately summarized.</em></span><strong>MMW&nbsp;›</strong></button>'}
function closeMmw(){MMW.request++;MMW.open=false;MMW.loading=false;MMW.error='';MMW.needsSetup=false;MMW.card=0;paintMusicStudio()}
function loadMmwMonth(month){var e=mmwEngine();if(!e||typeof e.summarize!=='function'){MMW.loading=false;MMW.error='MMW is still loading.';paintMusicStudio();return Promise.resolve(false)}month=String(month||mmwMonth());var mine=++MMW.request;MMW.month=month;MMW.loading=true;MMW.error='';MMW.needsSetup=false;MMW.data=null;MMW.summary=null;MMW.card=0;paintMusicStudio();return post({action:'listeningMonth',month:month}).then(function(r){if(mine!==MMW.request||!MMW.open)return false;var d=r&&r.data||{};MMW.loading=false;if(d.ok){MMW.data=d;MMW.summary=e.summarize(d,new Date());MMW.error='';MMW.needsSetup=false}else{MMW.needsSetup=!!d.needsSetup;MMW.error=d.error||'That month could not load.'}paintMusicStudio();return!!d.ok}).catch(function(){if(mine!==MMW.request||!MMW.open)return false;MMW.loading=false;MMW.error='That month could not load. Check your connection and try again.';paintMusicStudio();return false})}
function openMmw(){var e=mmwEngine();if(!e){myToast('MMW is still loading. Try once more.');return false}closeStudioDialog();musicFocusOpen=false;MMW.open=true;MMW.month=e.currentMonth(new Date());MMW.card=0;MMW.synced=true;paintMusicStudio();if(typeof listeningSync==='function')listeningSync();var flush=LISTENING&&LISTENING.flush?LISTENING.flush(true):Promise.resolve(true);return Promise.resolve(flush).catch(function(){return false}).then(function(ok){if(!MMW.open)return false;MMW.synced=ok!==false;return loadMmwMonth(MMW.month)})}
function shiftMmwMonth(dir){var e=mmwEngine();if(!e)return;var next=e.shiftMonth(mmwMonth(),Number(dir)<0?-1:1),current=e.currentMonth(new Date());if(next>current)return;loadMmwMonth(next)}
function mmwNum(value,digits){value=Number(value)||0;return value.toFixed(digits==null?0:digits)}
function mmwTrackLine(track){if(!track)return'<b>Still building</b><span>Keep listening in MAHFITT and this card will fill itself.</span>';return'<b>'+h(track.title||'MAHFITT Audio')+'</b><span>'+h(track.artist||track.sourceType||'MAHFITT')+'</span>'}
function mmwCard(kind,kicker,title,body,extra){return'<article class="mmw-card mmw-card--'+h(kind)+'" data-mmw-card><div class="mmw-card__inner"><small>'+h(kicker)+'</small><h4>'+h(title)+'</h4>'+body+(extra||'')+'</div></article>'}
function mmwStoryCards(summary){var e=mmwEngine(),month=summary.monthLabel,status=summary.partial?'SO FAR':'WRAPPED',top3=(summary.tracks||[]).slice(0,3),cards=[];
  cards.push(mmwCard('cover','MAHFITT MONTH WRAPPED',month,'<div class="mmw-covernum"><b>'+summary.totalMinutes+'</b><span>MINUTES PLAYED</span></div><div class="mmw-progress"><i style="width:'+Math.round(summary.progressPercent)+'%"></i></div><p>'+h(status)+' · '+summary.activeDays+' active day'+(summary.activeDays===1?'':'s')+'</p>'));
  cards.push(mmwCard('motion','YOUR MONTH IN MOTION','YOU KEPT IT MOVING','<div class="mmw-statgrid"><span><b>'+summary.totalMinutes+'</b><small>LISTENING MIN</small></span><span><b>'+summary.workoutMinutes+'</b><small>WORKOUT MIN</small></span><span><b>'+summary.uniqueTracks+'</b><small>TRACKS</small></span><span><b>'+summary.replays+'</b><small>REPLAYS</small></span></div><p>'+mmwNum(summary.workoutPercent,0)+'% of your listening happened inside a workout context.</p>'));
  cards.push(mmwCard('track','YOUR SOUND','#1 THIS MONTH','<div class="mmw-featuretrack">'+mmwTrackLine(summary.topTrack)+'</div>'+(top3.length?'<ol class="mmw-topthree">'+top3.map(function(t,i){return'<li><i>0'+(i+1)+'</i><span><b>'+h(t.title)+'</b><small>'+Math.round((Number(t.listenedSeconds)||0)/60)+' min</small></span></li>'}).join('')+'</ol>':'<p>Your top tracks will appear after meaningful listening time is recorded.</p>')));
  cards.push(mmwCard('training','TRAINING SOUNDTRACK','THE TRACK THAT WORKED WITH YOU','<div class="mmw-featuretrack">'+mmwTrackLine(summary.trainingTrack)+'</div><div class="mmw-bigline"><b>'+summary.workoutMinutes+'</b><span>MINUTES WITH TRAINING</span></div>'));
  cards.push(mmwCard('scene','YOUR ATMOSPHERE','THE WORLD YOU TRAINED IN','<div class="mmw-scenehero"><span class="mmw-scenehero__icon" data-scene="'+h(summary.favoriteScene&&summary.favoriteScene.id||'mesh')+'">'+themeEditIcon(summary.favoriteScene&&summary.favoriteScene.id||'mesh')+'</span><div><b>'+h(summary.favoriteScene&&summary.favoriteScene.label||'Color Haze')+'</b><small>'+h(summary.favoriteTheme&&summary.favoriteTheme.label||'MAHFITT Theme')+'</small></div></div><p>Scenes decorate the machine; your training geometry stayed locked.</p>'));
  var pitch=(summary.averagePitch>0?'+':'')+mmwNum(summary.averagePitch,1),speed=mmwNum(summary.averageSpeed||1,2)+'×';
  cards.push(mmwCard('mix','YOUR MIX','HOW YOU SHAPED THE SOUND','<div class="mmw-mixgrid"><span><b>'+speed+'</b><small>AVG SPEED</small></span><span><b>'+pitch+'</b><small>AVG PITCH</small></span><span><b>'+mmwNum(summary.reverbPercent,0)+'%</b><small>ROOM</small></span><span><b>'+mmwNum(summary.vhsPercent,0)+'%</b><small>VHS</small></span><span><b>'+mmwNum(summary.radioPercent,0)+'%</b><small>RADIO</small></span></div>'));
  var day=summary.longestDay&&e?e.dayLabel(summary.longestDay.day):'',hour=summary.favoriteHour&&e?e.hourLabel(summary.favoriteHour.hour):'',replay=summary.replayedTrack;
  cards.push(mmwCard('rhythm','YOUR RHYTHM','WHEN MAHFITT HIT DIFFERENT','<div class="mmw-rhythm"><span><small>BIGGEST DAY</small><b>'+h(day||'Still building')+'</b></span><span><small>FAVORITE HOUR</small><b>'+h(hour||'Still building')+'</b></span><span><small>MOST REPLAYED</small><b>'+h(replay&&replay.title||'Still building')+'</b></span></div>'));
  cards.push(mmwCard('final','MAHFITT · '+month,'THIS MONTH SOUNDS LIKE YOU','<p>'+h(e&&e.shareText?e.shareText(summary):'Your MAHFITT month, wrapped.')+'</p><button class="mmw-share" data-a="music-mmw-share">SHARE MONTH CARD</button><small class="mmw-private">Generated on your device · no public listening timeline</small>'));
  return cards;
}
function musicMmwHeaderHTML(){return'<header class="studio-head studio-head--mmw"><button class="mmw-headback" data-a="music-mmw-back" aria-label="Back to MAH PLAYER Library">‹</button><div class="mmw-headtitle"><span>MAHFITT</span><b>MONTH WRAPPED</b></div><button class="studio-head__close" data-a="music-close" aria-label="Close mah player">×</button></header>'}
