function musicMmwPanel(){var nav=mmwMonthNav();if(MMW.loading)return'<section class="studio-panel mmw-panel">'+nav+'<div class="mmw-loading"><i></i><b>BUILDING YOUR MONTH</b><span>Reading compact MAHFITT listening totals…</span></div></section>';if(MMW.needsSetup)return'<section class="studio-panel mmw-panel">'+nav+'<div class="mmw-empty"><b>MMW IS READY FOR ITS FIRST MONTH</b><span>Listening Intelligence has not been activated on this build yet. Your first accurate month starts when it is.</span></div></section>';if(MMW.error)return'<section class="studio-panel mmw-panel">'+nav+'<div class="mmw-empty"><b>THIS MONTH COULD NOT LOAD</b><span>'+h(MMW.error)+'</span><button data-a="music-mmw-retry">TRY AGAIN</button></div></section>';var summary=MMW.summary;if(!summary||!summary.hasData)return'<section class="studio-panel mmw-panel">'+nav+'<div class="mmw-empty"><b>'+h(summary&&summary.partial?'THIS MONTH IS JUST GETTING STARTED':'NO MAHFITT LISTENING FOR THIS MONTH')+'</b><span>MMW only counts meaningful playback inside MAHFITT. It does not reconstruct listening from before the tracker existed.</span></div></section>';var cards=mmwStoryCards(summary);return'<section class="studio-panel mmw-panel">'+nav+(MMW.synced?'':'<div class="mmw-syncnote">Offline/local listening will join this story after the next successful sync.</div>')+'<div class="mmw-story" data-mmw-story tabindex="0" aria-label="'+h(summary.monthLabel)+' Month Wrapped story">'+cards.join('')+'</div><div class="mmw-dots" aria-label="Story pages">'+cards.map(function(_,i){return'<button data-a="music-mmw-card" data-index="'+i+'" data-on="'+(i===MMW.card?'1':'0')+'" aria-label="Story card '+(i+1)+'"></button>'}).join('')+'</div></section>'}
function bindMmwStory(){if(!MMW.open)return;var host=document.querySelector('#musicStudio [data-mmw-story]');if(!host)return;var cards=host.querySelectorAll('[data-mmw-card]'),dots=document.querySelectorAll('#musicStudio .mmw-dots button'),raf=0;function paint(){raf=0;var width=host.clientWidth||1,index=Math.max(0,Math.min(cards.length-1,Math.round(host.scrollLeft/width)));MMW.card=index;dots.forEach(function(d,i){d.dataset.on=i===index?'1':'0'})}host.addEventListener('scroll',function(){if(raf)return;raf=requestAnimationFrame(paint)},{passive:true});if(MMW.card>0&&cards[MMW.card])requestAnimationFrame(function(){cards[MMW.card].scrollIntoView({behavior:'auto',block:'nearest',inline:'start'})})}
