/* v382. One authoritative place that stops every delayed Studio callback.
   A trailing rate/seek/EQ timer that survives a close can fire against the
   next track and overwrite a value the member just committed, which is exactly
   the "settings drift after prolonged use" failure. */
function cancelStudioTransportTimers(){
  if(studioRateTimer){clearTimeout(studioRateTimer);studioRateTimer=0}
  if(studioSeekTimer){clearTimeout(studioSeekTimer);studioSeekTimer=0}
  if(studioEqTimer){clearTimeout(studioEqTimer);studioEqTimer=0}
  if(reverseRateTimer){clearTimeout(reverseRateTimer);reverseRateTimer=0}
  if(studioPitchDetachTimer){clearTimeout(studioPitchDetachTimer);studioPitchDetachTimer=0}
  if(studioPitchRaf){cancelAnimationFrame(studioPitchRaf);studioPitchRaf=0}
  studioPitchInput=null;
  /* Theme and Studio own separate effect lifetimes. Cancelling a Studio drag
     must never cancel Theme's deferred Room send cut and leave convolution
     burning after the member has turned Theme Room off. */
  studioPitchDragging=false;studioRateDragging=false;studioRateDragInput=null;
}
