    function finish(error,duration){if(done)return;done=true;clearTimeout(timer);audio.removeAttribute('src');try{audio.load()}catch(x){}try{URL.revokeObjectURL(url)}catch(x){}if(error)reject(error);else resolve({file:file,duration:duration})}
