/* Storage speaks JSON at us. Members should never see it.
   Maps a failed signed-upload response onto one short MAHFITT line, and falls
   back to a status code rather than ever echoing a raw body. */
function storageUploadMessage(status,text){
  var code='',msg='';
  try{var j=JSON.parse(text||'{}');code=String(j.code||j.error||'');msg=String(j.message||'')}catch(e){}
  if(/InvalidMimeType|invalid_mime_type/i.test(code)||/mime/i.test(msg))return'That audio format is not supported yet. Use MP3, M4A, AAC, or WAV.';
  if(status===413||/EntityTooLarge|Payload/i.test(code))return'That file is too large. Keep it under 48 MB.';
  if(status===401||status===403)return'That upload link expired. Try the upload once more.';
  if(status===409)return'That file is already uploading. Give it a moment.';
  if(!status||status>=500)return'Storage is not responding. Try again in a moment.';
  return'Upload failed · '+(status||'network');
}
