function setDraftBpm(value,message){
  if(!THEME_DRAFT)return 0;var bpm=cleanBpm(value,0);THEME_DRAFT.bpm=bpm;syncThemeBpmEditor(message);if(S.theme&&themePlaying){themeBpm=bpm;syncMusicMotion()}return bpm;
}
function tapThemeBpm(){
  var now=(window.performance&&performance.now)?performance.now():Date.now(),known=THEME_DRAFT?cleanBpm(THEME_DRAFT.bpm,0):0;
  if(!bpmTapTimes.length||now-bpmTapTimes[bpmTapTimes.length-1]>2200)bpmTapTimes=[];
  /* When Auto BPM already supplied the tempo, the first tap while the song is
     playing is a phase calibration: tap on beat 1 and the animation's right / left
     apexes will then land on beats 2 / 4. Keep tapping if you also want to refine
     the tempo itself. */
  if(!bpmTapTimes.length&&known&&themePlaying){
    if(THEME_DRAFT){THEME_DRAFT.beatOffset=cleanBeatOffset(musicPlaybackTime(),0);themeBeatOffset=THEME_DRAFT.beatOffset}
    bpmTapTimes.push(now);setThemeBpm(known,THEME_DRAFT.beatOffset);syncThemeBpmEditor('Beat 1 locked · '+known+' BPM · apex hits beats 2 + 4 · keep tapping to refine');return known;
  }
  bpmTapTimes.push(now);if(bpmTapTimes.length>9)bpmTapTimes.shift();
  if(bpmTapTimes.length<3){syncThemeBpmEditor('Keep tapping to the beat…');return 0}
  var gaps=[];for(var i=1;i<bpmTapTimes.length;i++)gaps.push(bpmTapTimes[i]-bpmTapTimes[i-1]);gaps.sort(function(a,b){return a-b});
  var mid=Math.floor(gaps.length/2),median=gaps.length%2?gaps[mid]:(gaps[mid-1]+gaps[mid])/2,bpm=60000/median;
  while(bpm<45)bpm*=2;while(bpm>220)bpm/=2;
  bpm=Math.round(bpm*10)/10;
  if(THEME_DRAFT){THEME_DRAFT.beatOffset=themePlaying?cleanBeatOffset(musicPlaybackTime(),0):0;if(themePlaying)themeBeatOffset=THEME_DRAFT.beatOffset}
  return setDraftBpm(bpm,(themePlaying?'Beat locked · ':'Tapped · ')+bpm+' BPM · apex hits beats 2 + 4');
}
