function calendarMusicState(){
  var owner=activePlaybackOwner(),playing=owner==='studio'?studioPlaying:owner==='theme'?themePlaying:false,bpm=owner==='studio'?(studioBpm||120):(themeBpm||120),phase=0,t=normalizeTheme(S.theme||THEME_DEFAULT),transport=activeTransportState(),seek=songSeekState();
  try{phase=((musicPlaybackTime()*bpm/60)%1+1)%1}catch(e){phase=.52}
  return{type:'fob-music-state',owner:owner,playing:!!playing,studioPlaying:!!studioPlaying,themePlaying:!!themePlaying,bpm:bpm,phase:phase,masterVolume:cleanMasterVolume(MUSIC.masterVolume,1),transportOwner:transport.owner||'',provider:transport.provider||'',rate:transport.rate,speedEnabled:!!transport.speedEnabled,pitch:transport.pitch,pitchEnabled:!!transport.pitchEnabled,reverb:!!transport.reverb,effectsEnabled:!!transport.effectsEnabled,vhs:!!transport.vhs,vhsEnabled:!!transport.vhsEnabled,seekTime:seek.time,seekDuration:seek.duration,seekEnabled:!!seek.enabled,themeVisual:{primary:t.dark,secondary:t.accent,scene:t.scene,atmospherePalette:t.atmospherePalette.slice(0,6)}}
}
function handleCalendarAudioControl(data){
  data=data||{};var action=String(data.action||''),final=data.final!==false,state=activeTransportState(),seek=songSeekState(),value=Number(data.value),handled=false;
  if(action==='volume'&&isFinite(value)){setMasterVolumePercent(value,final,final);handled=true}
  else if(action==='rate'&&state.speedEnabled&&isFinite(value)){setActivePlaybackRate(value,final);handled=true}
  else if(action==='pitch'&&state.pitchEnabled&&isFinite(value)){queueStudioPitch(value,final);handled=true}
  else if(action==='seek'&&seek.enabled&&isFinite(value)){mediaSessionSeekTo(Math.max(0,Math.min(seek.duration,value)));handled=true}
  else if(action==='replay'){replayCurrent();handled=true}
  else if(action==='vhs'&&state.vhsEnabled){handled=toggleActivePlaybackVhs()!==false}
  else if(action==='reverb'&&state.effectsEnabled){toggleActivePlaybackReverb();handled=true}
  if(handled){paintTempoControl();syncMahfittMediaSession(true);setTimeout(postCalendarMusic,0)}
  return handled
}
