var bootPending=false;
/* Prefer the request the shell already started. Only when it used the same
   entry, and only once: a second boot (re-login, membership switch) must go to
   the network fresh rather than replay a stale payload. Any miss falls back to
   the ordinary post(), so this can never be the reason boot fails. */
function bootRequest(){
  var profile=savedCoachProfileId(),warm=window.__FOB_BOOT;window.__FOB_BOOT=null;
  if(warm&&warm.entry===ENTRY&&String(warm.profile||'')===String(profile||'')&&warm.p&&warm.p.then){
    return warm.p.then(function(r){return r||post({action:'boot',entry:ENTRY,activeProfileId:profile||undefined})});
  }
  return post({action:'boot',entry:ENTRY,activeProfileId:profile||undefined});
}
/* R71 — ONE canonical expired/blocked-session recovery owner.
   boot() owned this teardown inline. MAH PROTOCOL needed exactly the same
   behaviour for its own 401, and a second copy would have been a second
   authentication path. Behaviour for boot() is unchanged: the same owners are
   destroyed in the same order, the same token is cleared, the same login()
   screen is shown, and only a 403 writes the membership message. */
function mahfittSessionLost(status,message){
  destroyListeningIntelligence();stopThemeAudio();destroyYoutube();destroyTikTok();
  S.account=null;S.member=null;S.roleContext=null;S.theme=null;clearCoachProfileContext();applyTheme(THEME_DEFAULT);
  try{localStorage.removeItem(MEMBER_TOKEN_KEY)}catch(x){}
  login();
  var locked=document.getElementById('err');
  if(locked&&Number(status)===403)locked.textContent=message||'This member view is not available for that membership.';
  return true;
}
function resetFitnessContextRuntime(){
  clearActiveActivityRuntime();clearActiveWorkoutRuntime();if(typeof mahMediaResetState==='function')mahMediaResetState();
  S.progress=null;S.selected=null;S.q='';S.bookmarks=[];S.activeProgramId=null;S.activeDayIndex=null;
  try{TRAINING_FOUNDATION=null}catch(e){}try{PERIODIZATION_GUIDE=null;PERIODIZATION_DRAFT=null}catch(e){}
  try{MAH_PROTOCOL.loaded=false;MAH_PROTOCOL.error=''}catch(e){}
  try{resetCoachMessages()}catch(e){}
}
function resetPersonalAiRuntime(){
  MAHFITT_AI.loaded=false;MAHFITT_AI.messages=[];MAHFITT_AI.usage={day:'',count:0,limit:0,remaining:0};MAHFITT_AI.error='';MAHFITT_AI.draft='';MAHFITT_AI.pendingQuestion='';MAHFITT_AI.activeJob='chat';MAHFITT_AI.inlineJobs={prowork:null,retrowork:null};MAHFITT_AI.presentation={mode:'answer',selectedTurn:'',replayToken:0,expression:'helpful',responsePage:0,characterX:.18,assemblyY:0,entryGreeting:true,activeQuestion:''};fabiStopAnimation();
}
function boot(){
  if(bootPending)return;bindAudioSkip();bootPending=true;loading('FOB SYSTEMS','Loading your training…');
  bootRequest().then(function(r){
    if(r.status===403&&r.data&&r.data.code==='CLIENT_CONTEXT_FORBIDDEN'&&savedCoachProfileId()){
      clearCoachProfileContext();bootPending=false;boot();return;
    }
    if(r.status===401||r.status===403){mahfittSessionLost(r.status,r.data&&r.data.error);return}
    if(!r.data.ok){destroyListeningIntelligence();login();var e=document.getElementById('err');if(e)e.textContent=r.data.error||'Your membership was found, but training data could not load.';return}
    resetFitnessContextRuntime();resetPersonalAiRuntime();
    S.account=r.data.account||r.data.member;S.member=r.data.member;S.roleContext=r.data.roleContext||{isClientContext:false,canCoach:false,activeFitnessProfileId:S.member&&S.member.id,signedInAccountId:S.account&&S.account.id};
    saveCoachProfileContext();
    S.theme=normalizeTheme(r.data.theme||readLocalTheme()||THEME_DEFAULT);writeLocalTheme(S.theme);applyTheme(S.theme);setThemeAudio(S.theme);hydrateMusic(r.data.music);restoreMusicSelection();initListeningIntelligence();
    S.programs=mapMemberProgramRows(r.data.programs||[]);S.recent=r.data.recent||[];S.view='home';adoptActiveWorkout(r.data.activeWorkout||null);mahfittHistoryInit('home',{});
    if(S._afterFinishRoute){var doneTarget=String(S._afterFinishRoute||'calendar'),doneRoute=mahfittCurrentRoute(),doneDepth=doneRoute?Number(doneRoute.depth)||0:0;try{history.replaceState(mahfittRouteState(doneTarget,{source:'workout-complete'},doneDepth),'',location.href)}catch(routeError){}S._afterFinishRoute=''}
    bindMahfittHistorySwipe();mahfittRenderRoute(mahfittCurrentRoute()||mahfittRouteState('home',{},0));if(!handleEntryRoute()){maybeOpenMealGradientFromRoute();handleAudioEntry()}restoreActiveActivity();paintActiveWorkoutPersistent()
  }).finally(function(){bootPending=false})
}
