function coachInboxRowsHTML(){if(COACH_INBOX.busy&&!COACH_INBOX.loaded)return'<div class="coach-state"><b>OPENING INBOX…</b><span>Reading authorized client threads.</span></div>';if(COACH_INBOX.error)return'<div class="coach-state is-error"><b>MESSAGES COULD NOT LOAD</b><span>'+h(COACH_INBOX.error)+'</span><button class="ghost" data-a="coach-inbox-retry">TRY AGAIN</button></div>';if(!COACH_INBOX.threads.length)return'<div class="coach-state is-clear"><i>□</i><b>NO CLIENT MESSAGES YET</b><span>Threads will appear here when an authorized client sends or receives a message.</span></div>';return'<div class="coach-inbox-list">'+COACH_INBOX.threads.map(function(t){var m=t.latest||{},preview=m.body||'Open private thread';return'<button type="button" class="coach-inbox-row" data-a="coach-inbox-open" data-id="'+h(t.id)+'" data-name="'+h(t.name)+'"><span class="coach-inbox-row__identity"><b>'+h(t.name)+'</b>'+(t.unread?'<i>'+Math.min(99,Number(t.unread)||0)+'</i>':'')+'</span><span class="coach-inbox-row__preview">'+h(preview)+'</span><time>'+h(coachMessageTime(m.createdAt))+'</time><em aria-hidden="true">›</em></button>'}).join('')+'</div>'}
