function coachResourceClientName(id){var c=(COACH_DIRECTORY.clients||[]).find(function(x){return String(x.id)===String(id)});return c&&c.name||'Client'}
function coachResourceRowsHTML(){if(COACH_RESOURCES.busy&&!COACH_RESOURCES.loaded)return'<div class="coach-state"><b>OPENING LIBRARY…</b><span>Reading your coaching resources.</span></div>';if(COACH_RESOURCES.error)return'<div class="coach-state is-error"><b>RESOURCES COULD NOT LOAD</b><span>'+h(COACH_RESOURCES.error)+'</span><button class="ghost" data-a="coach-resources-retry">TRY AGAIN</button></div>';if(!COACH_RESOURCES.resources.length)return'<div class="coach-state is-clear"><i>◈</i><b>YOUR LIBRARY IS EMPTY</b><span>Add a link or text resource below. PDFs, images, and videos can be shared safely as browser links.</span></div>';var groups={};COACH_RESOURCES.resources.forEach(function(r){var k=String(r.category||'GENERAL');(groups[k]||(groups[k]=[])).push(r)});return Object.keys(groups).sort().map(function(cat){return'<section class="coach-resource-group"><h2>'+h(cat)+'</h2>'+groups[cat].map(function(r){var canManage=COACH_RESOURCES.storageAvailable!==false&&!r.builtin,opts=(COACH_DIRECTORY.clients||[]).map(function(c){return'<option value="'+h(c.id)+'">'+h(c.name)+'</option>'}).join(''),assigned=(r.assignments||[]).map(function(a){return'<button type="button" data-a="coach-resource-unassign" data-resource="'+h(r.id)+'" data-client="'+h(a.clientId)+'">'+h(coachResourceClientName(a.clientId))+' ×</button>'}).join('');return'<article class="coach-resource-card" data-builtin="'+(r.builtin?'1':'0')+'"><header><span>'+h(r.type==='text'?'TEXT':r.builtin?'BUILT-IN':'LINK')+'</span><b>'+h(r.title)+'</b></header>'+(r.type==='link'?'<a href="'+h(r.url)+'" target="_blank" rel="noopener noreferrer">OPEN RESOURCE ↗</a>':'<details><summary>READ RESOURCE</summary><p>'+h(r.body).replace(/\n/g,'<br>')+'</p></details>')+(canManage?'<div class="coach-resource-assign"><label><span>ASSIGN TO CLIENT</span><select id="resourceAssign_'+h(r.id)+'"><option value="">CHOOSE CLIENT…</option>'+opts+'</select></label><button type="button" data-a="coach-resource-assign" data-resource="'+h(r.id)+'">ASSIGN</button></div>'+(assigned?'<div class="coach-resource-assigned"><span>ASSIGNED</span>'+assigned+'</div>':'')+'<button type="button" class="coach-resource-archive" data-a="coach-resource-archive" data-resource="'+h(r.id)+'">ARCHIVE</button>':'')+'</article>'}).join('')+'</section>'}).join('')}
function coachResourceFormHTML(){if(COACH_RESOURCES.storageAvailable===false)return'<div class="coach-state is-clear coach-resource-fallback"><i>◈</i><b>BUILT-IN LIBRARY READY</b><span>Your shipped FOB resources are available above. Saved custom resources will return automatically when coach-library storage is available.</span></div>';return'<details class="coach-resource-new"><summary>＋ ADD RESOURCE</summary><div class="coach-resource-form"><label><span>TITLE</span><input id="coachResourceTitle" maxlength="120" placeholder="Protein guide"></label><label><span>CATEGORY</span><input id="coachResourceCategory" maxlength="60" placeholder="GENERAL"></label><label><span>TYPE</span><select id="coachResourceType"><option value="link">LINK / FILE</option><option value="text">TEXT</option></select></label><label data-resource-link><span>URL OR SITE FILE</span><input id="coachResourceUrl" maxlength="2000" placeholder="https://… or /file.pdf"></label><label data-resource-text hidden><span>TEXT</span><textarea id="coachResourceBody" maxlength="12000" rows="5" placeholder="Write the resource…"></textarea></label><span id="coachResourceStatus" role="status"></span><button type="button" class="ghost" data-a="coach-resource-create">SAVE RESOURCE</button></div></details>'}
function coachResourcesLoad(force){if(COACH_RESOURCES.busy)return;if(COACH_RESOURCES.loaded&&!force){if(COACH_RESOURCES.storageAvailable!==false&&!COACH_DIRECTORY.loaded&&!COACH_DIRECTORY.busy)coachDirectoryLoad(false);return}COACH_RESOURCES.busy=true;COACH_RESOURCES.error='';if(S.view==='coach-resources')coachResourcesPage(false);post({action:'coachResources'}).then(function(r){if(!r.data||!r.data.ok){COACH_RESOURCES.error=r.data&&r.data.error||'Resources are unavailable right now.';return}COACH_RESOURCES.resources=Array.isArray(r.data.resources)?r.data.resources:[];COACH_RESOURCES.storageAvailable=r.data.storageAvailable!==false;COACH_RESOURCES.degraded=!!r.data.degraded;COACH_RESOURCES.loaded=true}).finally(function(){COACH_RESOURCES.busy=false;if(COACH_RESOURCES.storageAvailable!==false&&!COACH_DIRECTORY.loaded&&!COACH_DIRECTORY.busy)coachDirectoryLoad(false);if(S.view==='coach-resources')coachResourcesPage(false)})}
function coachResourcesPage(load){if(isCoachClientContext()){mahfittNavigate('resources');return}S.view='coach-resources';root.innerHTML=coachPageShell('coach-resources','Resources','A simple coaching library for links, documents, media links, and text you actually use with clients.','<section class="coach-resource-shell">'+coachResourceRowsHTML()+coachResourceFormHTML()+'</section>');bindTempoControl();paintTempoControl();var type=document.getElementById('coachResourceType');if(type)type.onchange=coachResourceTypePaint;if(load!==false)coachResourcesLoad(false)}
function coachResourceTypePaint(){var type=document.getElementById('coachResourceType'),text=root.querySelector('[data-resource-text]'),link=root.querySelector('[data-resource-link]'),isText=type&&type.value==='text';if(text)text.hidden=!isText;if(link)link.hidden=!!isText}
function coachResourceCreate(){if(COACH_RESOURCES.busy)return;var title=document.getElementById('coachResourceTitle'),cat=document.getElementById('coachResourceCategory'),type=document.getElementById('coachResourceType'),url=document.getElementById('coachResourceUrl'),body=document.getElementById('coachResourceBody'),status=document.getElementById('coachResourceStatus');COACH_RESOURCES.busy=true;if(status)status.textContent='Saving…';post({action:'coachResourceCreate',title:title&&title.value,category:cat&&cat.value,type:type&&type.value,url:url&&url.value,body:body&&body.value}).then(function(r){if(!r.data||!r.data.ok){if(status)status.textContent=r.data&&r.data.error||'Resource could not be saved.';return}COACH_RESOURCES.loaded=false;COACH_RESOURCES.busy=false;coachResourcesLoad(true);return true}).finally(function(){COACH_RESOURCES.busy=false})}
function coachResourceAssign(resourceId,clientId,remove){if(!resourceId||!clientId)return Promise.resolve(false);var action=remove?'coachResourceUnassign':'coachResourceAssign';return post({action:action,resourceId:resourceId,clientId:clientId}).then(function(r){if(!r.data||!r.data.ok){myToast(r.data&&r.data.error||'Resource assignment could not change.');return false}COACH_RESOURCES.loaded=false;coachResourcesLoad(true);return true})}
