function mahHabitRowsHTML(){if(MAH_HABITS.busy&&!MAH_HABITS.loaded)return'<div class="coach-state"><b>READING TODAY…</b><span>Loading habits.</span></div>';if(MAH_HABITS.error)return'<div class="coach-state is-error"><b>HABITS COULD NOT LOAD</b><span>'+h(MAH_HABITS.error)+'</span><button class="ghost" data-a="habit-retry">TRY AGAIN</button></div>';if(!MAH_HABITS.habits.length)return'<div class="coach-state is-clear"><i>◇</i><b>NO ACTIVE HABITS</b><span>Add one simple behavior below.</span></div>';return'<div class="mah-habit-list">'+MAH_HABITS.habits.map(function(x){return'<article class="mah-habit-row" data-complete="'+(x.completed?'1':'0')+'"><button type="button" class="mah-habit-check" data-a="habit-toggle" data-id="'+h(x.id)+'" data-completed="'+(x.completed?'1':'0')+'" aria-label="'+(x.completed?'Mark incomplete':'Mark complete')+'"><i></i></button><span><b>'+h(x.title)+'</b><small>'+h(mahHabitSourceLabel(x.source))+'</small></span>'+(x.editable?'<button type="button" class="mah-habit-edit" data-a="habit-edit" data-id="'+h(x.id)+'">EDIT</button>':'')+'</article>'}).join('')+'</div>'}
