function mahHabitsPage(load){var key=String(S.member&&S.member.id||''),day=mahHabitDay();if(MAH_HABITS.clientKey&&MAH_HABITS.clientKey!==key){MAH_HABITS.loaded=false;MAH_HABITS.habits=[];MAH_HABITS.error='';MAH_HABITS.editId='';MAH_HABITS.editTitle=''}MAH_HABITS.clientKey=key;MAH_HABITS.day=day;S.view='mah-habits';if(isCoachClientContext()&&S.roleContext&&S.roleContext.permissions&&S.roleContext.permissions.habits===false){clientProtectedPage('MAH HABITS','Habit permission is not enabled for this coaching relationship.');return}root.innerHTML=mahfittBannerHTML('MAH HABITS','habits')+mahfittPageContextHTML('MAH HABITS','habits-page-context')+'<main class="home r85-member-tool-page mah-habits-page"><div class="backbar"><button class="back" data-a="progress">MAH Progress</button><span class="backbar__t">Simple behaviors</span></div><section class="training-page-intro"><span>MAH HABITS · TODAY</span><h1>'+h(isCoachClientContext()?S.member.name.toUpperCase():'ONE THING AT A TIME.')+'</h1><p>'+h(isCoachClientContext()?'Work with authorized habits through the same page your client uses.':'Repeatable behaviors for training, recovery, nutrition, and daily movement.')+'</p></section>'+mahHabitRowsHTML()+mahHabitFormHTML()+'</main>';bindTempoControl();paintTempoControl();if(load!==false)mahHabitsLoad(false)}
function mahHabitsLoad(force){if(MAH_HABITS.busy)return;if(MAH_HABITS.loaded&&!force)return;MAH_HABITS.busy=true;MAH_HABITS.error='';if(S.view==='mah-habits')mahHabitsPage(false);post({action:'habitList',day:MAH_HABITS.day||mahHabitDay()}).then(function(r){if(!r.data||!r.data.ok){MAH_HABITS.error=r.data&&r.data.error||'Habits are unavailable right now.';return}MAH_HABITS.habits=Array.isArray(r.data.habits)?r.data.habits:[];MAH_HABITS.loaded=true}).finally(function(){MAH_HABITS.busy=false;if(S.view==='mah-habits')mahHabitsPage(false)})}
function mahHabitEdit(id){var x=MAH_HABITS.habits.find(function(hb){return String(hb.id)===String(id)});if(!x||!x.editable)return;MAH_HABITS.editId=x.id;MAH_HABITS.editTitle=x.title||'';MAH_HABITS.editSchedule=x.schedule&&x.schedule.kind||'daily';mahHabitsPage(false);setTimeout(function(){var f=document.getElementById('mahHabitTitle');if(f)f.focus()},0)}
