function mahHabitToggle(id,completed){if(MAH_HABITS.busy)return;MAH_HABITS.busy=true;post({action:'habitToggle',habitId:id,day:MAH_HABITS.day||mahHabitDay(),completed:!completed}).then(function(r){if(!r.data||!r.data.ok){myToast(r.data&&r.data.error||'Habit could not be updated.');return}var x=MAH_HABITS.habits.find(function(hb){return String(hb.id)===String(id)});if(x)x.completed=!!r.data.completed;if(S.view==='mah-habits')mahHabitsPage(false)}).finally(function(){MAH_HABITS.busy=false})}
