function sharedCrownCollapsed(){try{return!!(window.MAHFITT_UI_STATE&&window.MAHFITT_UI_STATE.getCrownCollapsed())}catch(e){return false}}
/* ══ R71 — FIXED-COMPACT CROWN ON MR.MAH + MAH PROTOCOL ═══════════════════
   Those two pages keep the ordinary music crown permanently compact. The
   collapse chevron stays rendered, visible and focusable; it simply does
   nothing there, and neither does the crown swipe. Nothing on those pages ever
   writes the member's shared collapse preference, so every other page keeps
   behaving exactly as it did — including after the member toggles one.

   The discriminator is the crown's own hd--ai class, emitted only by the
   MR.MAH and MAH PROTOCOL renderers. S.view would over-match: Protocol runs
   under both 'protocol' and 'periodization', and the separate PERIODIZATION
   page renders hd--progress. The class also works for the delegated click
   owner that runs outside #mygym, which has no view state to consult. */
function crownLockedScope(extra){return /(^|\s)hd--ai(\s|$)/.test(String(extra||''))}
function crownLocked(crown){
  return !!(crown&&crown.classList&&typeof crown.classList.contains==='function'&&crown.classList.contains('hd--ai'));
}
function mahfittBannerHTML(page,scope,action,label,extra){
  scope=scope||'home';
  var locked=crownLockedScope(extra),
      homeClass=scope==='home'?' mf-banner--home':'',
      canCollapse=scope!=='health',
      /* Locked pages paint compact from the first frame, so a member whose
         saved preference is expanded never sees the tall rack flash in. The
         shared preference itself is read, never written. */
      collapsed=canCollapse&&(locked||sharedCrownCollapsed()),
      collapse=canCollapse
        ?'<button type="button" class="mf-banner__collapse" data-a="banner-collapse" aria-label="'+(collapsed?'Expand':'Collapse')+' audio crown" aria-expanded="'+(collapsed?'false':'true')+'"><svg class="mf-banner__chevron" viewBox="0 0 16 10" aria-hidden="true" focusable="false"><path d="M2.5 7.5 8 2.5l5.5 5"/></svg></button>'
        :'';
  return'<header class="hd mf-banner mf-banner--member'+homeClass+' '+h(extra||'')+'" data-collapsed="'+(collapsed?'1':'0')+'"'+(locked?' data-crown-locked="1"':'')+'>'
    +themeControls(scope)
    +crownMessageBtn()
    +'<span class="mf-banner__center">'+myWordmark(action,label)+logoTransportHTML()+'</span>'
    +tempoControlHTML(scope)
    +collapse
    +'</header>';
}
/* v439: one canonical crown-media state action. The button and the upper-right
   swipe gesture both call this function; neither path touches an audio owner. */
function paintBannerMediaCollapsed(crown,collapsed){
  if(!crown||!crown.classList||(!crown.classList.contains('mf-banner--member')&&!crown.classList.contains('mf-banner--workout')))return false;
  var button=crown.querySelector('[data-a="banner-collapse"]');if(!button)return false;
  /* Every state change funnels through here — button, swipe, and the shared
     storage event that repaints every crown. Clamping at this one point is
     what stops a toggle in a second tab expanding MR.MAH or Protocol behind
     the member's back. This paints only; it never writes shared state. */
  collapsed=crownLocked(crown)?true:!!collapsed;crown.setAttribute('data-collapsed',collapsed?'1':'0');
  button.setAttribute('aria-expanded',collapsed?'false':'true');button.setAttribute('aria-label',(collapsed?'Expand':'Collapse')+' audio crown');return true;
}
function syncBannerMediaCollapsed(collapsed){
  document.querySelectorAll('.mf-banner--member:not(.mf-banner--workout),.mf-banner--workout').forEach(function(crown){paintBannerMediaCollapsed(crown,collapsed)});
}
function setBannerMediaCollapsed(crown,collapsed){
  if(!paintBannerMediaCollapsed(crown,collapsed))return false;
  /* Defence in depth: a locked crown is painted, but the member's shared
     preference is left exactly as they last set it on a normal page. */
  if(crownLocked(crown))return true;
  collapsed=!!collapsed;
  try{if(window.MAHFITT_UI_STATE)collapsed=window.MAHFITT_UI_STATE.setCrownCollapsed(collapsed)}catch(e){}
  syncBannerMediaCollapsed(collapsed);return true;
}
function toggleBannerMediaCollapsed(crown){if(Date.now()<crownSwipeBlockUntil)return false;if(crownLocked(crown))return false;var current=crown?crown.getAttribute('data-collapsed')==='1':sharedCrownCollapsed();return setBannerMediaCollapsed(crown,!current)}
if(window.MAHFITT_UI_STATE&&typeof window.MAHFITT_UI_STATE.subscribe==='function')window.MAHFITT_UI_STATE.subscribe(function(collapsed){syncBannerMediaCollapsed(collapsed)});
var CROWN_SWIPE_CLAIM_PX=18,CROWN_SWIPE_COMMIT_PX=34,CROWN_SWIPE_DOMINANCE=1.25,crownSwipe=null,crownSwipeBlockUntil=0;
function crownSwipeDirection(dx,dy,threshold){
  var ax=Math.abs(Number(dx)||0),ay=Math.abs(Number(dy)||0),need=Number(threshold)||CROWN_SWIPE_COMMIT_PX;
  if(ay<need||ay<ax*CROWN_SWIPE_DOMINANCE)return 0;
  return dy<0?-1:1;
}
function crownSwipeHitZone(crown,target,x,y){
  if(!crown||!target||!target.closest)return false;
  /* Refuse before the gesture is CLAIMED. Blocking later, at touchend, would
     mean crownSwipeTouch had already called preventDefault() during the move
     and stolen the page's own vertical scroll. */
  if(crownLocked(crown))return false;
  var collapse=target.closest('[data-a="banner-collapse"]');
  if(!collapse&&target.closest('button,input,select,textarea,a,[role="button"],[data-a],.mah-songseek,.fobtempo__rail'))return false;
  var r=crown.getBoundingClientRect&&crown.getBoundingClientRect();if(!r||!isFinite(r.right))return false;
  var zoneW=Math.min(260,Math.max(96,r.width*.32)),zoneH=Math.min(104,Math.max(58,r.height*.38));
  /* Live Workout shares crown state, not ordinary-crown geometry. Its candidate
     pocket stays tighter so workout rails/transports retain gesture ownership. */
  if(crown.classList&&crown.classList.contains('mf-banner--workout')){zoneW=Math.min(180,Math.max(92,r.width*.28));zoneH=Math.min(92,Math.max(54,r.height*.30))}
  return x>=r.right-zoneW&&x<=r.right&&y>=r.top&&y<=r.top+zoneH;
}
function crownSwipeTouch(e,phase){
  if(!e||(!e.changedTouches&&phase==='end'))return;
  if(phase==='start'){
    var touch=e.touches&&e.touches[0];if(!touch)return;
    var crown=e.target&&e.target.closest&&(e.target.closest('.mf-banner--member:not(.mf-banner--workout)')||e.target.closest('.mf-banner--workout'));
    if(!crown||!crown.querySelector('[data-a="banner-collapse"]')||!crownSwipeHitZone(crown,e.target,touch.clientX,touch.clientY)){crownSwipe=null;return}
    crownSwipe={id:touch.identifier,x:touch.clientX,y:touch.clientY,crown:crown,claimed:false};return;
  }
  if(!crownSwipe)return;
  var list=phase==='move'?e.touches:e.changedTouches,touch=null;
  for(var i=0;list&&i<list.length;i++)if(list[i].identifier===crownSwipe.id){touch=list[i];break}
  if(!touch){if(phase==='end')crownSwipe=null;return}
  var dx=touch.clientX-crownSwipe.x,dy=touch.clientY-crownSwipe.y;
  if(phase==='move'){
    if(!crownSwipe.claimed&&crownSwipeDirection(dx,dy,CROWN_SWIPE_CLAIM_PX))crownSwipe.claimed=true;
    if(crownSwipe.claimed&&e.cancelable)e.preventDefault();
    return;
  }
  var state=crownSwipe,dir=crownSwipeDirection(dx,dy,CROWN_SWIPE_COMMIT_PX);crownSwipe=null;
  if(!dir)return;
  setBannerMediaCollapsed(state.crown,dir<0);crownSwipeBlockUntil=Date.now()+320;
}
document.addEventListener('touchstart',function(e){crownSwipeTouch(e,'start')},{passive:true});
document.addEventListener('touchmove',function(e){crownSwipeTouch(e,'move')},{passive:false});
document.addEventListener('touchend',function(e){crownSwipeTouch(e,'end')},{passive:true});
document.addEventListener('touchcancel',function(){crownSwipe=null},{passive:true});

/* ══ R48 — PERIODIZATION / BODY PROGRESS / MOVEMENT / PROGRAM CREATOR ════
   These pages extend canonical backend owners. They never write workout
   history to make a plan look successful, and they never claim a Watch or
   HealthKit connection the web runtime cannot actually prove. */
var TRAINING_DEFS={
  'Macrocycle':'The whole mission. It is the full stretch of training aimed at one big goal.',
  'Mesocycle':'A chapter inside the mission. For a few cycles, training focuses more heavily on one specific job.',
  'Microcycle':'One full repeat of your workout routine. That does not have to mean seven days — if your routine takes 10 days to repeat, that full loop can be one workout cycle.',
  'Progressive Overload':'Make training a little harder when your body is ready. That might mean one more rep, a little more weight, another set, more distance, incline, resistance, or another useful change — not everything at once.',
  'Deload':'A short easier stretch so you can recover before pushing hard again.',
  'Volume':'How much work you do — like hard sets, reps, distance, or time.',
  'Intensity':'How hard the work is. That can mean weight, pace, speed, or how close you are to your limit.',
  'Frequency':'How often you train something.',
  'RPE':'A 1–10 effort scale. A bigger number means the set felt harder.',
  'RIR':'How many good reps you think you still had left before failure.',
  'BMI':'How heavy are you compared with your height? It cannot tell muscle from fat, so a really muscular person can score high too.',
  'Body Fat %':'About how much of your body weight is fat. Tape-measure formulas are estimates, not perfect scans.',
  'FFMI':'How much lean mass you carry for your height. Higher usually means more muscular or more jacked. Very high numbers can look steroid-level, but FFMI cannot prove PED or steroid use.'
};
function trainingDefButton(term){return'<button type="button" class="training-term" data-a="training-definition" data-term="'+h(term)+'">'+h(term)+'</button>'}
function closeTrainingDefinition(){var m=document.getElementById('mahTrainingDefinition');if(m)m.remove();document.body.classList.remove('training-definition-open');syncMahfittOverlayOwnership();if(TRAINING_RETURN_FOCUS&&TRAINING_RETURN_FOCUS.focus)try{TRAINING_RETURN_FOCUS.focus()}catch(e){}TRAINING_RETURN_FOCUS=null}
function openTrainingDefinition(term){term=String(term||'');if(!TRAINING_DEFS[term])return;closeTrainingDefinition();TRAINING_RETURN_FOCUS=document.activeElement;var m=document.createElement('section');m.id='mahTrainingDefinition';m.className='training-definition-overlay';m.style.cssText='position:fixed!important;inset:0!important;display:grid!important;place-items:center!important;padding:18px!important;z-index:10080!important;box-sizing:border-box!important';m.innerHTML='<button class="training-definition-back" data-a="training-definition-close" aria-label="Close definition"></button><article class="training-definition-card" style="position:relative!important;width:min(560px,calc(100vw - 36px))!important;max-height:80dvh!important;margin:auto!important;border-radius:6px!important;overflow:auto!important" role="dialog" aria-modal="true" aria-labelledby="trainingDefinitionTitle"><header><span>MAHFITT DEFINITION</span><button data-a="training-definition-close" aria-label="Close">×</button></header><h2 id="trainingDefinitionTitle">'+h(term)+'</h2><p>'+h(TRAINING_DEFS[term])+'</p></article>';document.body.appendChild(m);document.body.classList.add('training-definition-open');syncMahfittOverlayOwnership();setTimeout(function(){var x=m.querySelector('header button');if(x)x.focus()},0)}
function trainingCopy(x){return JSON.parse(JSON.stringify(x||{}))}
function trainingToday(){return new Date().toISOString().slice(0,10)}
function trainingUid(prefix){return String(prefix||'n')+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function trainingDatePretty(x){if(!x)return'—';try{return new Date(x+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}).toUpperCase()}catch(e){return String(x)}}
function trainingFoundationApply(data){data=data||{};TRAINING_FOUNDATION.loaded=true;TRAINING_FOUNDATION.coreAvailable=true;TRAINING_FOUNDATION.error='';TRAINING_FOUNDATION.plans=Array.isArray(data.plans)?data.plans:[];TRAINING_FOUNDATION.profile=data.profile||null;TRAINING_FOUNDATION.measurements=Array.isArray(data.measurements)?data.measurements:[];TRAINING_FOUNDATION.healthDays=Array.isArray(data.healthDays)?data.healthDays:[];TRAINING_FOUNDATION.activitySegments=Array.isArray(data.activitySegments)?data.activitySegments:[]}
