function periodizationProgramChanged(plan){var p=periodProgramById(plan&&plan.linkedProgramId);return!!(p&&plan&&plan.programRevision&&periodProgramRevision(p)&&String(plan.programRevision)!==String(periodProgramRevision(p)))}
function periodGeneratedHTML(plan,active){var path=periodizationCurrentPath(plan),changed=periodizationProgramChanged(plan),cycles=periodizationFlattenCycles(plan);return'<section class="period-generated" data-active="'+(active?'1':'0')+'"><header><div><span>'+trainingDefButton('Macrocycle')+'</span><h2>'+h(plan.name||'Your plan')+'</h2></div><b>'+h((plan.durationUnit==='weeks'?'WEEKS':'WORKOUT CYCLES'))+'</b></header>'+(changed?'<aside class="period-program-changed"><b>PROGRAM UPDATED</b><p>Your workout changed since this periodization was built.</p><button data-a="period-update">UPDATE PERIODIZATION</button></aside>':'')+(active?periodizationTimelineHTML(plan):'')+'<div class="period-chapter-list">'+(plan.mesocycles||[]).map(function(m,mi){return'<article class="period-chapter" data-current="'+(path.meso===m?'1':'0')+'"><header><em>'+String(mi+1).padStart(2,'0')+'</em><div><span>'+trainingDefButton('Mesocycle')+'</span><b>'+h(m.name||('Chapter '+(mi+1)))+'</b></div></header><p>'+h(m.goal||m.focus||'')+'</p><small>'+h(String(m.durationCount||((m.microcycles||[]).length)||1))+' '+h(m.durationUnit==='weeks'?'WEEK'+(Number(m.durationCount)===1?'':'S'):'WORKOUT CYCLE'+(Number(m.durationCount)===1?'':'S'))+'</small><div class="period-cycle-strip">'+(m.microcycles||[]).map(function(mc){var ci=cycles.findIndex(function(x){return x.micro===mc}),current=active&&ci===path.index;return'<div data-current="'+(current?'1':'0')+'"><span>'+h(mc.name)+'</span><b>'+h(mc.whatChanges||mc.progressionTarget||'Hold')+'</b><small>WHY · '+h(mc.why||'Based on the plan and real completed work.')+'</small></div>'}).join('')+'</div></article>'}).join('')+'</div><section class="period-overload"><header><div><span>'+trainingDefButton('Progressive Overload')+'</span><h2>PLANNED ↔ ACTUAL</h2></div></header>'+periodizationPlannedActualHTML(plan)+'<p>Completed workouts stay historical truth. The overlay reacts to them; it never rewrites them.</p></section>'+(active?'<section class="period-next"><span>NEXT RECOMMENDED CHANGE</span><b>'+h(path.micro&&path.micro.nextRecommendation||'Complete the current cycle, then review actual performance.')+'</b></section><button class="period-help-link" data-a="period-help">HOW PERIODIZATION WORKS</button>':'<div class="period-optin"><button class="mg-button" data-a="period-use">USE THIS PERIODIZATION</button><button data-a="period-not-yet">NOT YET / KEEP MY PROGRAM AS-IS</button></div>')+'</section>'}
function periodizationPage(coachMode){coachMode=coachMode===true||S.view==='coach-periodization';S.view=coachMode?'coach-periodization':'periodization';var active=periodizationEnrolledPlan(),g=periodGuideLoad();if(active&&!g.rebuilding&&!PERIODIZATION_DRAFT)PERIODIZATION_DRAFT=trainingCopy(active);var program=periodProgramById(g.selectedProgramId),backAction=coachMode?'program-library':'progress',backLabel=coachMode?'Program Library':'MAH Progress',html=mahfittBannerHTML('PERIODIZATION','periodization',backAction,'Back to '+backLabel,'hd--progress')+mahfittPageContextHTML('PERIODIZATION','progress-page-context')+'<main class="home periodization-view"><div class="backbar"><button class="back" data-a="'+backAction+'">'+backLabel+'</button><span class="backbar__t">'+(coachMode?'Client program structure':'Guided training planning')+'</span></div><section class="training-page-intro"><span>PERIODIZATION</span><h1>TURN YOUR PROGRAM INTO A PLAN THAT ADAPTS</h1><p>MAHFITT looks at the program you already use, asks a few simple questions, then organizes your training into understandable cycles. You do not need to know exercise-science jargon first.</p></section>'+trainingInlineStatusHTML(coachMode?'coach-periodization':'periodization');if(active&&!g.rebuilding){html+=periodizationProgramSummary(periodProgramById(active.linkedProgramId))+periodGeneratedHTML(PERIODIZATION_DRAFT||active,true);if(g.showHelp)html+=periodEducationHTML();html+='</main>';root.innerHTML=html;bindTempoControl();paintTempoControl();return}html+=periodEducationHTML()+'<section class="period-guide"><header><span>1 · SHOW MAHFITT THE PROGRAM</span><b>WHAT ARE WE PERIODIZING?</b></header>'+periodizationProgramSummary(program);if(S.programs.length>1)html+='<label class="period-program-select"><span>CHOOSE CURRENT PROGRAM</span><select data-period-select-program><option value="">CHOOSE…</option>'+S.programs.map(function(p){var id=periodProgramId(p);return'<option value="'+h(id)+'" '+(id===g.selectedProgramId?'selected':'')+'>'+h(p.name||'Program')+'</option>'}).join('')+'</select></label>';else if(!S.programs.length)html+='<div class="period-no-program"><b>NO SAVED PROGRAM YET</b><p>Create or save a program first. Periodization needs something real to sit on top of.</p></div>';html+='<header class="period-guide-step"><span>2 · A FEW SHORT QUESTIONS</span><b>MAHFITT ONLY ASKS WHAT IT CANNOT SAFELY INFER</b></header><div class="period-question-list">'+PERIOD_QUESTIONS.map(function(q,i){return periodQuestionHTML(q,i,g.answers)}).join('')+'</div>'+(g.error?'<div class="period-guide-error">'+h(g.error)+'</div>':'')+'<button class="mg-button period-generate" data-a="period-generate" '+(!program?'disabled':'')+'>BUILD MY PERIODIZATION</button></section>';if(PERIODIZATION_DRAFT&&PERIODIZATION_DRAFT.generatedAt)html+=periodGeneratedHTML(PERIODIZATION_DRAFT,false);html+='</main>';root.innerHTML=html;bindTempoControl();paintTempoControl()}
function periodizationInput(t){var g=periodGuideLoad();if(t.dataset&&t.dataset.periodAnswer){g.answers[t.dataset.periodAnswer]=t.value.slice(0,900);g.error='';periodGuideSave();return}if(t.dataset&&t.dataset.periodSelectProgram!=null){g.selectedProgramId=t.value;PERIODIZATION_DRAFT=null;g.error='';periodGuideSave();periodizationPage();return}}
function periodizationNewPlan(){PERIODIZATION_DRAFT=null;PERIODIZATION_GUIDE=null;try{localStorage.removeItem(periodGuideStorageKey())}catch(e){}periodizationPage()}
function periodizationAddMeso(){myToast('MAHFITT now builds mesocycles from the guided answers.')}
function periodizationRemoveMeso(){myToast('Guided Periodization keeps cycle structure together.')}
function periodizationAddMicro(){myToast('Workout cycles are generated from your current program.')}
function periodizationRemoveMicro(){myToast('Workout cycles are generated from your current program.')}
function savePeriodizationPlan(after){var p=PERIODIZATION_DRAFT;if(!p)return Promise.resolve(false);return post({action:'periodizationSave',id:p.id||'',version:p.version||1,plan:p}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Plan could not save.');PERIODIZATION_DRAFT=trainingCopy(r.data.plan);var ix=TRAINING_FOUNDATION.plans.findIndex(function(x){return String(x.id)===String(r.data.plan.id)});if(ix>=0)TRAINING_FOUNDATION.plans[ix]=trainingCopy(r.data.plan);else TRAINING_FOUNDATION.plans.unshift(trainingCopy(r.data.plan));if(typeof after==='function')after(r.data.plan);return true}).catch(function(e){myToast(e.message||'Plan could not save.');return false})}
function periodizationUse(){if(!PERIODIZATION_DRAFT||!PERIODIZATION_DRAFT.generatedAt){myToast('Build the periodization first.');return}PERIODIZATION_DRAFT.enrollmentState='active';savePeriodizationPlan(function(){var g=periodGuideLoad();g.rebuilding=false;g.replacePlanId='';g.replaceVersion=0;periodGuideSave();periodizationPage();myToast('Periodization is now active. Your old workouts were not changed.')})}
function periodizationNotYet(){if(!PERIODIZATION_DRAFT)return;PERIODIZATION_DRAFT.enrollmentState='not_yet';savePeriodizationPlan(function(){PERIODIZATION_DRAFT=null;periodizationPage();myToast('Your program stays as-is.')})}
function periodizationUpdatePlan(){var active=periodizationEnrolledPlan();if(!active)return;var program=periodProgramById(active.linkedProgramId);if(!program)return;PERIODIZATION_GUIDE={selectedProgramId:periodProgramId(program),answers:trainingCopy(active.questionnaire||{}),showHelp:true,error:'Your current answers are loaded. Review them, then rebuild against the updated program.',busy:false,rebuilding:true,replacePlanId:active.id||'',replaceVersion:Number(active.version)||1};PERIODIZATION_DRAFT=null;periodGuideSave();periodizationPage()}
function periodVoiceStopStream(){var st=PERIODIZATION_VOICE.stream;PERIODIZATION_VOICE.stream=null;if(st&&st.getTracks)st.getTracks().forEach(function(t){try{t.stop()}catch(e){}})}
function periodVoiceFinish(){var r=PERIODIZATION_VOICE.recorder;if(!r||r.state==='inactive')return;PERIODIZATION_VOICE.state='transcribing';periodizationPage();try{r.stop()}catch(e){PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error='Voice recording could not finish.';periodizationPage()}}
function periodVoiceStart(field){if(!retroworkVoiceSupported()){PERIODIZATION_VOICE.field=field;PERIODIZATION_VOICE.error='Voice is unavailable here. Typed answers still work.';periodizationPage();return}var token=++PERIODIZATION_VOICE.token;PERIODIZATION_VOICE.field=field;PERIODIZATION_VOICE.error='';PERIODIZATION_VOICE.state='requesting';periodizationPage();navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}).then(function(stream){if(token!==PERIODIZATION_VOICE.token){stream.getTracks().forEach(function(t){t.stop()});return}var mime=retroworkRecorderMime(),rec;try{rec=mime?new MediaRecorder(stream,{mimeType:mime,audioBitsPerSecond:32000}):new MediaRecorder(stream)}catch(e){rec=new MediaRecorder(stream)}PERIODIZATION_VOICE.stream=stream;PERIODIZATION_VOICE.recorder=rec;PERIODIZATION_VOICE.chunks=[];rec.ondataavailable=function(ev){if(ev&&ev.data&&ev.data.size)PERIODIZATION_VOICE.chunks.push(ev.data)};rec.onstop=function(){var chunks=PERIODIZATION_VOICE.chunks.slice(),type=rec.mimeType||mime||'audio/webm';PERIODIZATION_VOICE.recorder=null;PERIODIZATION_VOICE.chunks=[];periodVoiceStopStream();if(token!==PERIODIZATION_VOICE.token)return;var blob=new Blob(chunks,{type:type});if(!blob.size){PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error='No speech was captured.';periodizationPage();return}retroworkBlobBase64(blob).then(function(audioBase64){return post({action:'retroworkTranscribe',audioBase64:audioBase64,mimeType:blob.type||'audio/webm'})}).then(function(res){if(token!==PERIODIZATION_VOICE.token)return;if(!res.data||!res.data.ok)throw new Error(res.data&&res.data.error||'Voice transcription failed.');var text=String(res.data.transcript||'').trim();if(!text)throw new Error('No speech was detected.');var g=periodGuideLoad();g.answers[field]=retroworkJoinTranscript(g.answers[field],text).slice(0,900);periodGuideSave();PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error='';periodizationPage()}).catch(function(err){if(token!==PERIODIZATION_VOICE.token)return;PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error=err.message||'Voice transcription failed. Typed answers are unchanged.';periodizationPage()})};rec.onerror=function(){PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error='Microphone recording was interrupted.';periodVoiceStopStream();periodizationPage()};rec.start();PERIODIZATION_VOICE.state='recording';periodizationPage()}).catch(function(e){if(token!==PERIODIZATION_VOICE.token)return;PERIODIZATION_VOICE.state='idle';PERIODIZATION_VOICE.error=String(e&&e.name)==='NotAllowedError'?'Microphone permission was denied. Typed answers still work.':'Microphone could not start. Typed answers still work.';periodVoiceStopStream();periodizationPage()})}
