function bodyWeightSeries(){var by={};(TRAINING_FOUNDATION.healthDays||[]).forEach(function(d){var w=d&&d.metrics&&Number(d.metrics.bodyWeightLb);if(Number.isFinite(w))by[d.day]={date:d.day,weight:w,source:d.source||'apple_health'}});(TRAINING_FOUNDATION.measurements||[]).forEach(function(m){var w=Number(m.weight_lb);if(Number.isFinite(w))by[m.measured_on]={date:m.measured_on,weight:w,source:m.source||'manual'}});return Object.keys(by).sort().map(function(k){return by[k]})}
function bodyLatestMeasurement(){var s=bodyWeightSeries(),weights=s.length?s[s.length-1]:null,rows=TRAINING_FOUNDATION.measurements||[],waists=rows.filter(function(m){return m.waist_in!=null}).sort(function(a,b){return String(a.measured_on).localeCompare(String(b.measured_on))}),bodyFats=rows.filter(function(m){return m.body_fat_pct!=null}).sort(function(a,b){return String(a.measured_on).localeCompare(String(b.measured_on))});return{weight:weights&&weights.weight||null,waist:waists.length?Number(waists[waists.length-1].waist_in):null,bodyFatPct:bodyFats.length?Number(bodyFats[bodyFats.length-1].body_fat_pct):null}}
function bodyProfileModel(){var x=TRAINING_FOUNDATION.profile||{};return{ageYears:x.age_years==null?'':Number(x.age_years),heightIn:x.height_in==null?'':Number(x.height_in),goalWeightLb:x.goal_weight_lb==null?'':Number(x.goal_weight_lb),bodyFatFormulaSex:x.body_fat_formula_sex||'',useEstimatedBodyFatForFfmi:!!x.use_estimated_body_fat_for_ffmi,goalBodyFatPct:x.goal_body_fat_pct==null?'':Number(x.goal_body_fat_pct),goalFfmi:x.goal_ffmi==null?'':Number(x.goal_ffmi),tdeeFormulaSex:x.tdee_formula_sex||'',activityFactor:x.activity_factor==null?'':Number(x.activity_factor),deficitDeltaKcal:x.deficit_delta_kcal==null?500:Number(x.deficit_delta_kcal),surplusDeltaKcal:x.surplus_delta_kcal==null?250:Number(x.surplus_delta_kcal),proteinGPerLb:x.protein_g_per_lb==null?.8:Number(x.protein_g_per_lb),fatGPerLb:x.fat_g_per_lb==null?.3:Number(x.fat_g_per_lb),macroScenario:x.macro_scenario||'maintenance'}}
function bodyRfmEstimate(heightIn,waistIn,sex){heightIn=Number(heightIn);waistIn=Number(waistIn);sex=String(sex||'');if(!Number.isFinite(heightIn)||heightIn<=0||!Number.isFinite(waistIn)||waistIn<=0||['male','female'].indexOf(sex)<0)return null;var value=(sex==='male'?64:76)-20*(heightIn/waistIn);return Number.isFinite(value)&&value>1&&value<70?value:null}
function bodyFatSeries(){var p=bodyProfileModel(),height=Number(p.heightIn),sex=p.bodyFatFormulaSex,by={};(TRAINING_FOUNDATION.measurements||[]).forEach(function(m){var date=String(m.measured_on||'');if(!date)return;var manual=Number(m.body_fat_pct);if(Number.isFinite(manual)&&manual>0&&manual<70){by[date]={date:date,value:manual,low:manual,high:manual,source:'manual',estimated:false};return}var waist=Number(m.waist_in),estimate=bodyRfmEstimate(height,waist,sex);if(estimate!=null){by[date]={date:date,value:estimate,low:Math.max(1,estimate-3),high:Math.min(69,estimate+3),source:'rfm-estimate',estimated:true,waist:waist}}});return Object.keys(by).sort().map(function(k){return by[k]})}
function bodyBmiSeries(){var p=bodyProfileModel(),height=Number(p.heightIn);if(!Number.isFinite(height)||height<=0)return[];return bodyWeightSeries().map(function(x){return{date:x.date,value:x.weight*703/(height*height),source:x.source||'weight'}})}
function bodyFfmiFrom(weight,heightIn,bodyFatPct){weight=Number(weight);heightIn=Number(heightIn);bodyFatPct=Number(bodyFatPct);if(!Number.isFinite(weight)||weight<=0||!Number.isFinite(heightIn)||heightIn<=0||!Number.isFinite(bodyFatPct)||bodyFatPct<=0||bodyFatPct>=70)return null;var hm=heightIn*.0254,leanKg=weight*(1-bodyFatPct/100)*.45359237,raw=leanKg/(hm*hm);return{raw:raw,normalized:raw+6.1*(1.8-hm)}}
function bodyFfmiSeries(){var p=bodyProfileModel(),height=Number(p.heightIn),fatBy={};bodyFatSeries().forEach(function(x){if(!x.estimated||p.useEstimatedBodyFatForFfmi)fatBy[x.date]=x});if(!Number.isFinite(height)||height<=0)return[];return bodyWeightSeries().map(function(w){var bf=fatBy[w.date],f=bf&&bodyFfmiFrom(w.weight,height,bf.value);return f?{date:w.date,value:f.normalized,raw:f.raw,source:bf.source,estimated:!!bf.estimated,bodyFatPct:bf.value}:null}).filter(Boolean)}
function bodyLatestBodyFat(){var s=bodyFatSeries();return s.length?s[s.length-1]:null}
function bodyCalculations(){var p=bodyProfileModel(),latest=bodyLatestMeasurement(),bfRow=bodyLatestBodyFat(),w=Number(latest.weight),hgt=Number(p.heightIn),age=Number(p.ageYears),bmi=Number.isFinite(w)&&w>0&&Number.isFinite(hgt)&&hgt>0?w*703/(hgt*hgt):null,ffmi=null,ffmiNormalized=null,tdee=null,bf=bfRow?Number(bfRow.value):null;if(Number.isFinite(bf)&&(!bfRow.estimated||p.useEstimatedBodyFatForFfmi)){var f=bodyFfmiFrom(w,hgt,bf);if(f){ffmi=f.raw;ffmiNormalized=f.normalized}}if(Number.isFinite(w)&&w>0&&Number.isFinite(hgt)&&hgt>0&&Number.isFinite(age)&&age>0&&['male','female'].indexOf(p.tdeeFormulaSex)>=0&&Number.isFinite(Number(p.activityFactor))&&Number(p.activityFactor)>0){var kg=w*.45359237,cm=hgt*2.54,bmr=10*kg+6.25*cm-5*age+(p.tdeeFormulaSex==='male'?5:-161);tdee=bmr*Number(p.activityFactor)}var deficit=tdee==null?null:Math.max(0,tdee-Number(p.deficitDeltaKcal||0)),surplus=tdee==null?null:tdee+Number(p.surplusDeltaKcal||0),scenario=p.macroScenario==='deficit'?deficit:p.macroScenario==='surplus'?surplus:tdee,protein=null,fat=null,carbs=null;if(scenario!=null&&Number.isFinite(w)&&w>0){var proteinTarget=Math.max(0,w*Number(p.proteinGPerLb||0));protein=Math.min(proteinTarget,Math.max(0,scenario/4));var afterProtein=Math.max(0,scenario-protein*4),fatTarget=Math.max(0,w*Number(p.fatGPerLb||0));fat=Math.min(fatTarget,afterProtein/9);carbs=Math.max(0,(scenario-protein*4-fat*9)/4)}return{bmi:bmi,ffmi:ffmi,ffmiNormalized:ffmiNormalized,bodyFatPct:Number.isFinite(bf)?bf:null,bodyFatEstimated:!!(bfRow&&bfRow.estimated),bodyFatLow:bfRow?bfRow.low:null,bodyFatHigh:bfRow?bfRow.high:null,tdee:tdee,deficit:deficit,surplus:surplus,scenario:scenario,protein:protein,fat:fat,carbs:carbs}}
function bodyTdeeHTML(){var c=bodyCalculations(),p=bodyProfileModel(),latest=bodyLatestMeasurement(),result=c.tdee==null?'—':Math.round(c.tdee).toLocaleString('en-US')+' KCAL';return'<section class="body-calc-card body-tdee-calculator" data-body-calc-card="tdee"><header><div><span>'+trainingDefButton('TDEE')+'</span><h3>DAILY ENERGY ESTIMATE</h3></div><b>'+result+'</b></header><p><strong>Super simple:</strong> TDEE is MAHFITT’s estimate of how many calories your body uses across a normal day. It needs your current weight, height, age, a Mifflin formula input and an activity factor. It is a planning estimate, not a metabolic-lab measurement.</p><div class="body-tdee-context"><span><small>CURRENT WEIGHT</small><b>'+(latest.weight==null?'—':latest.weight.toFixed(1)+' LB')+'</b></span><span><small>HEIGHT</small><b>'+(Number(p.heightIn)>0?bodyHeightLabel(Number(p.heightIn)):'—')+'</b></span><span><small>ACTIVITY</small><b>'+(Number(p.activityFactor)>0?Number(p.activityFactor).toFixed(3):'—')+'</b></span></div><div class="body-input-grid body-tdee-inputs"><label><span>AGE</span><select data-body-profile="ageYears">'+bodyNumberOptions(10,100,p.ageYears,1,"CHOOSE AGE")+'</select></label><label><span>MIFFLIN FORMULA INPUT</span><select data-body-profile="tdeeFormulaSex"><option value="">NOT SET</option><option value="male" '+(p.tdeeFormulaSex==='male'?'selected':'')+'>MALE FORMULA</option><option value="female" '+(p.tdeeFormulaSex==='female'?'selected':'')+'>FEMALE FORMULA</option></select></label><label><span>ACTIVITY FACTOR</span><select data-body-profile="activityFactor"><option value="">CHOOSE</option><option value="1.2" '+(Number(p.activityFactor)===1.2?'selected':'')+'>1.20 · LOW</option><option value="1.375" '+(Number(p.activityFactor)===1.375?'selected':'')+'>1.375 · LIGHT</option><option value="1.55" '+(Number(p.activityFactor)===1.55?'selected':'')+'>1.55 · MODERATE</option><option value="1.725" '+(Number(p.activityFactor)===1.725?'selected':'')+'>1.725 · HIGH</option><option value="1.9" '+(Number(p.activityFactor)===1.9?'selected':'')+'>1.90 · VERY HIGH</option></select></label></div><button class="body-profile-save" data-a="body-profile-save">SAVE TDEE INPUTS</button><small class="body-tdee-note">Height and current weight come from BODY PROGRESS so every MAHFITT tool reads the same body data.</small></section>'}
/* ══ MAH PROTOCOL — canonical member owner ═════════════════════════════════
   MAH PROTOCOL is the approachable umbrella over the systems MAHFITT already
   owns. It is ONE surface with four phases (overview / onboarding / draft /
   schedule), not a second planning system: the plan record is still
   member_periodization_plans, the program is still the canonical Program
   Editor, body data is still Body Progress, photos are still MAH MEDIA, and
   scheduling still lands in the one member_calendar_events table through one
   authoritative server write path.

   Member-facing wording is deliberately plain. The exercise-science terms stay
   available behind WHAT DOES THIS MEAN? and remain the internal vocabulary. */
var PROTOCOL_PATHS=[
  {id:'acrobat',label:'ACROBAT',desc:'Relative strength, mobility, body control, athletic movement.'},
  {id:'brawler',label:'BRAWLER',desc:'Muscular density, power, strength, and hard work capacity.'},
  {id:'titan',label:'TITAN',desc:'Maximum strength and muscular size.'},
  {id:'sprinter',label:'SPRINTER',desc:'Speed, explosiveness, athletic legs, and power.'},
  {id:'ranger',label:'RANGER',desc:'Endurance, durability, conditioning, and a lean athletic direction.'},
  {id:'hybrid',label:'HYBRID',desc:'Balanced strength, muscle, mobility, and conditioning.'}
];
