  version:{tag:'UPDATE',act:'RETRY',say:'This MAHFITT app is newer than the server answering it. MAH PROTOCOL needs the matching server update.'},
  server:{tag:'SERVICE',act:'RETRY',say:'The MAHFITT service could not answer. Nothing you entered was lost. Try again.'}
