/* PHOTO-002/005 — consent and ownership are checked before anything is sent,
   and the failure of this optional step never blocks the Protocol. */
function protocolVisualRun(){
  if(MAH_PROTOCOL.visualBusy)return;
  var inputs=protocolInputs(),ids=protocolMulti('visualMediaIds');
  if(!inputs.consentAdult||!inputs.consentOwnImages){MAH_PROTOCOL.visualError='Confirm both consent boxes before MAHFITT looks at your photos.';protocolPage();return}
  if(!ids.length){MAH_PROTOCOL.visualError='Choose at least one MAH MEDIA photo, or skip this step entirely.';protocolPage();return}
  MAH_PROTOCOL.visualBusy=true;MAH_PROTOCOL.visualError='';protocolPage();
  post({action:'protocolVisualReview',mediaIds:ids,
    consent:{adult:!!inputs.consentAdult,ownImages:!!inputs.consentOwnImages},
    targetPhysiquePath:inputs.targetPhysiquePath||null,primaryGoal:inputs.primaryGoal||''}).then(function(r){
    MAH_PROTOCOL.visualBusy=false;
    if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'The optional visual review could not run.');
    if(r.data.preferences)MAH_PROTOCOL.preferences=r.data.preferences;
    MAH_PROTOCOL.visualStale=false;
    protocolStepTo(PROTOCOL_STEP_COUNT);
  }).catch(function(e){
    MAH_PROTOCOL.visualBusy=false;
    MAH_PROTOCOL.visualError=(e.message||'The optional visual review could not run.')+' You can skip this step and still build a full Protocol.';
    protocolPage();
  });
}
/* PHOTO-004 — clears the analysis only. The MAH MEDIA entries are untouched. */
function protocolVisualClear(){
  mahfittAiConfirm('Clear the optional visual physique review? Your MAH MEDIA photos are not deleted.',function(){
    post({action:'protocolVisualClear'}).then(function(r){
      if(r.data&&r.data.ok){
        MAH_PROTOCOL.preferences=r.data.preferences||MAH_PROTOCOL.preferences;
        MAH_PROTOCOL.visualStale=false;protocolInputs().visualMediaIds=[];
        myToast('Visual review cleared. Your photos are still in MAH MEDIA.');
      }else myToast(r.data&&r.data.error||'The visual review could not be cleared.');
      protocolPage();
    }).catch(function(){myToast('The visual review could not be cleared.');protocolPage()});
  });
}
/* CAL-001 — the proposal is turned into real local datetimes here, then sent to
   the server for conflict review. Nothing is written by this call. */
function protocolScheduleItemsFromPlan(plan){
  var body=plan&&plan.protocol||{},proposal=Array.isArray(body.calendarProposal)?body.calendarProposal:[];
  var start=body.startDateProposal&&/^\d{4}-\d{2}-\d{2}$/.test(body.startDateProposal)?body.startDateProposal:protocolTodayKey();
  return proposal.map(function(p){
    var base=new Date(start+'T00:00:00');
    base.setDate(base.getDate()+(Number(p.dayOffset)||0));
    base.setMinutes(base.getMinutes()+(Number(p.startMinute)||0));
    var end=new Date(base.getTime()+(Number(p.durationMinutes)||30)*60000);
    return{key:String(p.key||''),startsAt:base.toISOString(),endsAt:end.toISOString(),
      title:p.title||'MAH Protocol',itemType:p.itemType||'workout',programDayIndex:p.programDayIndex==null?null:Number(p.programDayIndex)};
  }).filter(function(x){return x.key});
}
function protocolScheduleOpen(){
  var plan=protocolActivePlan();
  if(!plan){myToast('Save your Protocol first.');return}
  var items=protocolScheduleItemsFromPlan(plan);
  if(!items.length){myToast('This Protocol has no proposed schedule yet.');return}
  MAH_PROTOCOL.phase='schedule';MAH_PROTOCOL.scheduleError='';MAH_PROTOCOL.schedule=null;protocolPage();
  post({action:'protocolScheduleReview',planId:plan.id,items:items}).then(function(r){
    if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'The schedule review could not load.');
    MAH_PROTOCOL.schedule=r.data;protocolPage();
  }).catch(function(e){
    /* FAIL-002 — the Protocol itself survives; it simply stays unscheduled. */
    MAH_PROTOCOL.schedule={items:[],counts:{}};
    MAH_PROTOCOL.scheduleError=(e.message||'The schedule review could not load.')+' Your Protocol is saved and simply stays unscheduled for now.';
    protocolPage();
  });
}
function protocolScheduleDrop(index){
  var s=MAH_PROTOCOL.schedule;if(!s||!Array.isArray(s.items))return;
  s.items.splice(Number(index),1);
  s.counts={total:s.items.length,
    new:s.items.filter(function(r){return r.state==='new'}).length,
    existing:s.items.filter(function(r){return r.state==='existing'}).length,
    conflict:s.items.filter(function(r){return r.state==='conflict'}).length};
  protocolPage();
}
function protocolScheduleMove(index){
  var s=MAH_PROTOCOL.schedule;if(!s||!Array.isArray(s.items))return;
  var it=s.items[Number(index)];if(!it||!it.alternate)return;
  it.startsAt=it.alternate.startsAt;it.endsAt=it.alternate.endsAt;it.state='new';it.conflicts=[];it.alternate=null;
  s.counts={total:s.items.length,
    new:s.items.filter(function(r){return r.state==='new'}).length,
    existing:s.items.filter(function(r){return r.state==='existing'}).length,
    conflict:s.items.filter(function(r){return r.state==='conflict'}).length};
  protocolPage();
}
/* CAL-003/CAL-009 — one confirmed request to the one authoritative server write
   path. Repeating it reuses the same rows. */
function protocolScheduleCommit(){
  var s=MAH_PROTOCOL.schedule,plan=protocolActivePlan();
  if(MAH_PROTOCOL.scheduleBusy||!s||!plan)return;
  var items=(s.items||[]).filter(function(it){return it.state!=='conflict'});
  if(!items.length){myToast('Nothing is left to add. Move or remove the conflicting items first.');return}
  mahfittAiConfirm('Add '+items.length+' Protocol item'+(items.length===1?'':'s')+' to MAH Calendar? Existing events are never overwritten, and your paid FOB / LIFT SESH bookings cannot be changed by this.',function(){
    MAH_PROTOCOL.scheduleBusy=true;MAH_PROTOCOL.scheduleError='';protocolPage();
    post({action:'protocolScheduleCommit',planId:plan.id,items:items.map(function(it){
      return{key:it.key,startsAt:it.startsAt,endsAt:it.endsAt,title:it.title,itemType:it.itemType,programDayIndex:it.programDayIndex}})}).then(function(r){
      MAH_PROTOCOL.scheduleBusy=false;
      if(r.status===409||r.data&&r.data.code==='PROTOCOL_SCHEDULE_CONFLICT'){
        MAH_PROTOCOL.scheduleError='Your Calendar changed after review. Nothing was written. Review the changed items below, then move or remove the conflicts.';
        return post({action:'protocolScheduleReview',planId:plan.id,items:items}).then(function(rr){if(rr.data&&rr.data.ok)MAH_PROTOCOL.schedule=rr.data;protocolPage()});
      }
      if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'The schedule could not be added.');
      MAH_PROTOCOL.phase='overview';MAH_PROTOCOL.schedule=null;protocolLoad(true);myToast('Added to MAH Calendar.');
    }).catch(function(e){
      MAH_PROTOCOL.scheduleBusy=false;
      MAH_PROTOCOL.scheduleError=e.message||'The schedule could not be added.';
      protocolPage();
    });
  });
}

