function bodyDerivedHTML(){var c=bodyCalculations(),p=bodyProfileModel(),fmt=function(v,u){return v==null?'—':Math.round(v).toLocaleString('en-US')+(u||'')};return'<section class="body-derived"><div><span>'+trainingDefButton('BMI')+'</span><b>'+(c.bmi==null?'—':c.bmi.toFixed(1))+'</b></div><div><span>'+trainingDefButton('Body Fat %')+'</span><b>'+(c.bodyFatPct==null?'—':c.bodyFatPct.toFixed(1)+'%'+(c.bodyFatEstimated?' EST.':''))+'</b></div><div><span>TDEE · ESTIMATED</span><b>'+fmt(c.tdee,' KCAL')+'</b></div><div><span>DEFICIT · ESTIMATED</span><b>'+fmt(c.deficit,' KCAL')+'</b></div><div><span>SURPLUS · ESTIMATED</span><b>'+fmt(c.surplus,' KCAL')+'</b></div><div><span>PROTEIN</span><b>'+fmt(c.protein,' G')+'</b></div><div><span>CARBOHYDRATE</span><b>'+fmt(c.carbs,' G')+'</b></div><div><span>FAT</span><b>'+fmt(c.fat,' G')+'</b></div><p>'+(c.tdee==null?'TDEE is unavailable until age, height, weight, a Mifflin formula sex input and activity factor are provided. MAHFITT will not invent missing inputs.':'Macros reconcile to the selected '+h(String(p.macroScenario||'maintenance').toUpperCase())+' calorie scenario within rounding tolerance.')+'</p></section>'}
