function bodyLastSyncedLabel(){try{var t=localStorage.getItem('fob.mahfitt.body.lastSynced');if(!t)return'';var d=new Date(t);return isNaN(+d)?'':' · LAST SYNCED '+d.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).toUpperCase()}catch(e){return''}}
function bodyMarkSynced(){try{localStorage.setItem('fob.mahfitt.body.lastSynced',new Date().toISOString())}catch(e){}}
function saveBodyProfile(){
  bodySaveStatus('Saving…','busy');
  return post({action:'bodyProfileSave',profile:bodyProfileFormPayload()}).then(function(r){
    if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'');
    TRAINING_FOUNDATION.profile=r.data.profile||TRAINING_FOUNDATION.profile;
    bodyMarkSynced();
    bodySaveStatus('SAVED'+bodyLastSyncedLabel(),'ok');
    return true;
  }).catch(function(e){
    /* DATA-005 — never surface backend/developer jargon to a normal user. */
    var raw=String(e&&e.message||'');
    var human=/migration|schema|supabase|sql|backend|undefined|network/i.test(raw)||!raw
      ? 'We could not save your body numbers just now. Your entries are still on screen.'
      : raw;
    bodySaveStatus(human,'error');
    return false;
  });
}
function saveBodyMeasurement(){
  var date=(document.getElementById('bodyMeasureDate')||{}).value||'',
      weight=(document.getElementById('bodyMeasureWeight')||{}).value||'',
      waist=(document.getElementById('bodyMeasureWaist')||{}).value||'',
      fat=(document.getElementById('bodyMeasureBodyFat')||{}).value||'';
  if(!date){myToast('Choose the measurement date first.');return Promise.resolve(false)}
  if(weight===''&&waist===''&&fat===''){myToast('Enter weight, waist or body fat.');return Promise.resolve(false)}
  return post({action:'bodyMeasurementSave',measuredOn:date,weightLb:weight===''?null:Number(weight),waistIn:waist===''?null:Number(waist),bodyFatPct:fat===''?null:Number(fat)}).then(function(r){
    if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'');
    var list=TRAINING_FOUNDATION.measurements||[],row=r.data.measurement;
    if(row){var ix=list.findIndex(function(x){return String(x.measured_on)===String(row.measured_on)});if(ix>=0)list[ix]=row;else list.push(row);TRAINING_FOUNDATION.measurements=list}
    bodyMarkSynced();
    myToast('Measurement saved.');
    bodyProgressPage();
    return true;
  }).catch(function(e){
    var raw=String(e&&e.message||'');
    myToast(/migration|schema|supabase|sql|backend|undefined/i.test(raw)||!raw?'We could not save that measurement just now. Try again in a moment.':raw);
    return false;
  });
}
function bodyProgressPage(){S.view='body-progress';var p=bodyProfileModel(),latest=bodyLatestMeasurement(),html=mahfittBannerHTML('BODY PROGRESS','body-progress','progress','Back to MAH Progress','hd--progress')+mahfittPageContextHTML('BODY PROGRESS','progress-page-context')+'<main class="home body-progress-view"><div class="backbar"><button class="back" data-a="progress">MAH Progress</button><span class="backbar__t">Body Progress</span></div><section class="training-page-intro body-metrics-intro"><span>BODY PROGRESS</span><h1>TRACK BODY METRICS</h1><p><b>WHAT YOU ARE ENTERING:</b> the basic numbers that describe your body right now. MAHFITT reuses this one source for your progress graphs, Activity estimates, BMI, body-fat estimate, FFMI and TDEE.</p><nav class="training-page-directory" aria-label="Body page directory"><button data-a="body-jump" data-target="bodyProfileSection">PROFILE</button><button data-a="body-jump" data-target="bodyMeasurementSection">MEASUREMENTS</button><button data-a="body-jump" data-target="bodyProgressSection">PROGRESS</button><button data-a="calculators">CALCULATORS</button></nav></section>'+trainingInlineStatusHTML('body-progress')+'<section class="body-input-panel body-input-panel--simple" id="bodyProfileSection"><header><span>1 · BODY PROFILE</span><b>THE SLOW-CHANGING STUFF</b></header><p class="body-section-explain">Height helps the body calculators make sense. Goals are optional markers for your graphs. The tape-formula choice is only used when you ask MAHFITT to estimate body fat.</p><div class="body-input-grid body-input-grid--essentials"><label><span>HEIGHT · FT</span><select data-body-height="feet">'+bodyNumberOptions(3,8,bodyHeightParts(p.heightIn).feet,1,"FT")+'</select></label><label><span>HEIGHT · IN</span><select data-body-height="inches">'+bodyNumberOptions(0,11.5,bodyHeightParts(p.heightIn).inches,0.5,"IN")+'</select></label><label><span>BODY-FAT TAPE FORMULA</span><select data-body-profile="bodyFatFormulaSex"><option value="">CHOOSE FORMULA</option><option value="male" '+(p.bodyFatFormulaSex==='male'?'selected':'')+'>MALE RFM FORMULA</option><option value="female" '+(p.bodyFatFormulaSex==='female'?'selected':'')+'>FEMALE RFM FORMULA</option></select></label><label><span>GOAL WEIGHT · LB</span><input type="number" min="1" max="1500" step="0.1" data-body-profile="goalWeightLb" value="'+h(p.goalWeightLb)+'" placeholder="optional"></label><label><span>GOAL BODY FAT · %</span><select data-body-profile="goalBodyFatPct">'+bodyNumberOptions(1,69,p.goalBodyFatPct,0.5,"OPTIONAL")+'</select></label><label><span>GOAL FFMI</span><select data-body-profile="goalFfmi">'+bodyNumberOptions(10,40,p.goalFfmi,1,"OPTIONAL")+'</select></label><label class="body-estimate-toggle"><input type="checkbox" data-body-profile="useEstimatedBodyFatForFfmi" '+(p.useEstimatedBodyFatForFfmi?'checked':'')+'><span>ALLOW TAPE ESTIMATE FOR FFMI</span></label></div><button class="body-profile-save" data-a="body-profile-save">SAVE PROFILE + GOALS</button></section><section class="body-input-panel body-input-panel--measurement" id="bodyMeasurementSection"><header><span>2 · TODAY\'S MEASUREMENT</span><b>WHAT CHANGED RIGHT NOW?</b></header><p class="body-section-explain">Weight is the main number Activity also reuses. Waist lets MAHFITT make a simple tape-based body-fat estimate. If you already know a measured body-fat %, enter it; otherwise leave it blank.</p><div class="body-measure-row"><label><span>DATE</span><input id="bodyMeasureDate" type="date" value="'+trainingToday()+'"></label><label><span>CURRENT WEIGHT · LB</span><input id="bodyMeasureWeight" type="number" min="1" max="1500" step="0.1" value="" placeholder="'+(latest.weight!=null?h(latest.weight.toFixed(1)):'')+'"></label><label><span>WAIST · IN</span><select id="bodyMeasureWaist">'+bodyNumberOptions(15,80,"",0.5,latest.waist!=null?("LAST · "+latest.waist.toFixed(1)+" IN"):"CHOOSE WAIST")+'</select></label><label><span>BODY FAT · %</span><select id="bodyMeasureBodyFat">'+bodyNumberOptions(1,69,"",0.5,"OPTIONAL MEASURED %")+'</select></label><button data-a="body-measure-save">SAVE MEASUREMENT</button></div><p class="body-input-help">Tape estimate: measure your waist around the belly-button area while relaxed. Do not suck in. MAHFITT labels the result ESTIMATED because a tape is not a body scan.</p></section><section class="body-calculators-entry"><span>3 · MAH CALCULATORS</span><h2>BMI · BODY FAT · FFMI · TDEE</h2><p>The calculator page uses the body data above. No duplicate profile, no extra calculator clutter.</p><button data-a="calculators">OPEN MAH CALCULATORS</button></section><div id="bodyProgressSection">'+bodyMainGraphHTML()+'</div></main>';root.innerHTML=html;bindTempoControl();paintTempoControl()}
function dedupeHealthSamples(samples){var seen={},out=[];(Array.isArray(samples)?samples:[]).forEach(function(x){x=x||{};var k=[x.type||'',x.start||x.startedAt||'',x.end||x.endedAt||'',Number(x.value)||0,x.unit||'',x.sourceId||x.source||''].join('|');if(seen[k])return;seen[k]=1;out.push(x)});return out}
