function activityFobbingMet(row){return{easy:4,moderate:6,hard:8,very_hard:10}[row&&row.effort_level]||6}
function activityMetClient(row){if(!row)return 4;if(row.activity_type==='fobbing')return activityFobbingMet(row);if(ACTIVITY_TYPE_MET[row.activity_type])return ACTIVITY_TYPE_MET[row.activity_type];if(row.activity_type==='run')return 8.3;if(row.activity_type==='walk')return Math.max(3,3.5+Math.min(15,Math.max(0,Number(row.incline_pct)||0))*.08);return{easy:2.8,moderate:4,hard:6,very_hard:8}[row.effort_level]||4}
function activityLiveCalories(row){if(!row)return null;if(row.active_energy_kcal!=null&&row.energy_source==='healthkit')return{value:Number(row.active_energy_kcal),measured:true};var weight=Number(row.body_weight_lb)||activityCanonicalWeight(),minutes=activityElapsedMs(row)/60000;if(!Number.isFinite(weight)||weight<=0||minutes<=0)return{value:0,measured:false};var kcal=activityMetClient(row)*3.5*(weight*.45359237)/200*minutes;return{value:Math.max(0,kcal),measured:false}}
