function activityBrowserMotionBegin(){activityBrowserMotionStop();var row=ACTIVE_ACTIVITY.row;if(!ACTIVE_ACTIVITY.motionAllowed||!row||(row.activity_type!=='walk'&&row.activity_type!=='run'))return;ACTIVE_ACTIVITY.stepEstimator=activityStepEstimatorNew(row.activity_type);ACTIVE_ACTIVITY.motionListener=function(e){var r=ACTIVE_ACTIVITY.row;if(!r||r.state!=='active')return;var st=ACTIVE_ACTIVITY.stepEstimator||(ACTIVE_ACTIVITY.stepEstimator=activityStepEstimatorNew(r.activity_type)),dynamic=activityMotionDynamicMagnitude(e,st),result=activityStepEstimatorSample(st,dynamic,Date.now());ACTIVE_ACTIVITY.stepEstimator=result.state;if(result.count>0){r.steps=Math.max(0,Number(r.steps)||0)+result.count;r.source_summary=Object.assign({},r.source_summary||{},{runtime:'web',metricSource:'browser_estimate',estimator:'cadence_v2',estimated:true});activityBrowserCheckpointSave(r);paintActivityMini();activityBrowserEstimateSync(false)}};window.addEventListener('devicemotion',ACTIVE_ACTIVITY.motionListener,{passive:true})}
