function activityMiniMount(){var el=document.getElementById('mahActivityMini');if(!el){el=document.createElement('aside');el.id='mahActivityMini';el.className='activity-mini';document.body.appendChild(el)}return el}
function activityMiniHTML(row,compact){var kcal=activityLiveCalories(row),steps=row&&row.steps!=null?Number(row.steps).toLocaleString('en-US'):'—',elapsed=activityDurationText(activityElapsedMs(row)),title=activityTitleClient(row);if(compact)return'<button class="activity-mini-diamond" data-activity-mini="expand" aria-label="Open live '+h(title)+'"><span>◆</span><i></i></button>';return'<div class="activity-mini-panel"><button class="activity-mini-collapse" data-activity-mini="collapse" aria-label="Collapse live Activity">◇</button><div class="activity-mini-copy"><span>'+h(title)+'</span><b>'+elapsed+'</b></div><div class="activity-mini-metric"><span>CALORIES</span><b>'+Math.round(kcal&&kcal.value||0)+' <small>'+(kcal&&kcal.measured?'MEASURED':'~')+'</small></b></div>'+((row.activity_type==='walk'||row.activity_type==='run')?'<div class="activity-mini-metric"><span>STEPS</span><b>'+steps+' <small>'+(row.steps==null?'':(activityMetricMeasured(row,'steps')?'MEASURED':'~'))+'</small></b></div>':'')+'<div class="activity-mini-actions"><button data-activity-mini="'+(row.state==='paused'?'resume':'pause')+'">'+(row.state==='paused'?'RESUME':'PAUSE')+'</button><button data-activity-mini="finish">FINISH</button></div></div>'}
function paintActivityMini(){var el=activityMiniMount(),row=ACTIVE_ACTIVITY.row;if(!row||row.state==='closed'){el.hidden=true;el.innerHTML='';return}el.hidden=false;var compact=ACTIVE_ACTIVITY.collapsed||S.view==='workout';el.dataset.compact=compact?'1':'0';el.innerHTML=activityMiniHTML(row,compact)}
function activityTickStart(){
  clearInterval(ACTIVE_ACTIVITY.tick);ACTIVE_ACTIVITY.tick=0;
  if(!ACTIVE_ACTIVITY.row||ACTIVE_ACTIVITY.row.state==='closed'){paintActivityMini();return}
  paintActivityMini();
  ACTIVE_ACTIVITY.tick=setInterval(function(){
    if(!ACTIVE_ACTIVITY.row||ACTIVE_ACTIVITY.row.state==='closed'){
      clearInterval(ACTIVE_ACTIVITY.tick);ACTIVE_ACTIVITY.tick=0;return;
    }
    paintActivityMini();
    if(S.view==='movement'){
      var timer=root.querySelector('[data-live-activity-time]');
      if(timer)timer.textContent=activityDurationText(activityElapsedMs(ACTIVE_ACTIVITY.row));
      var kcal=root.querySelector('[data-live-activity-kcal]'),k=activityLiveCalories(ACTIVE_ACTIVITY.row);
      if(kcal)kcal.textContent=Math.round(k&&k.value||0)+' '+(k&&k.measured?'MEASURED':'~');
    }
  },1000);
}
