function activitySetupOpen(type){if(ACTIVE_ACTIVITY.row&&ACTIVE_ACTIVITY.row.state!=='closed'){myToast('Finish the current Activity before starting another.');return}ACTIVITY_SETUP={type:type,activityLabel:'',inclinePct:0,targetMinutes:'',effortLevel:'moderate'};movementPage()}
