function activityStart(){if(ACTIVE_ACTIVITY.busy)return;var weight=activityCanonicalWeight(),type=ACTIVITY_SETUP.type;if(weight==null){myToast('Add body weight in Body Progress first.');return}if(type==='misc'&&!String(ACTIVITY_SETUP.activityLabel||'').trim()){myToast('Name the Misc Activity first.');return}ACTIVE_ACTIVITY.busy=true;activityRequestMotionPermission(type).then(function(ok){ACTIVE_ACTIVITY.motionAllowed=!!ok;var key='activity-'+(window.crypto&&crypto.randomUUID?crypto.randomUUID():trainingUid('live'));return post({action:'activityStart',activityType:type,activityLabel:ACTIVITY_SETUP.activityLabel,inclinePct:ACTIVITY_SETUP.inclinePct,targetMinutes:ACTIVITY_SETUP.targetMinutes,effortLevel:ACTIVITY_SETUP.effortLevel,clientKey:key})}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Activity could not start.');if(ACTIVE_ACTIVITY.motionAllowed&&(type==='walk'||type==='run')&&r.data.activity.steps==null)r.data.activity.steps=0;ACTIVITY_SETUP.type='';activityAdopt(r.data.activity);myToast(activityTitleClient(r.data.activity)+' started.')}).catch(function(e){ACTIVE_ACTIVITY.error=e.message||'Activity could not start.';myToast(ACTIVE_ACTIVITY.error)}).finally(function(){ACTIVE_ACTIVITY.busy=false})}
function activityTransition(action){if(ACTIVE_ACTIVITY.busy||!ACTIVE_ACTIVITY.row)return;ACTIVE_ACTIVITY.busy=true;var api=action==='pause'?'activityPause':'activityResume';post({action:api,id:ACTIVE_ACTIVITY.row.id}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Activity could not update.');activityAdopt(r.data.activity)}).catch(function(e){myToast(e.message||'Activity could not update.')}).finally(function(){ACTIVE_ACTIVITY.busy=false})}
function activityFinish(){if(ACTIVE_ACTIVITY.busy||!ACTIVE_ACTIVITY.row)return;ACTIVE_ACTIVITY.busy=true;var ending=ACTIVE_ACTIVITY.row;activityBrowserCheckpointSave(ending);activityBrowserEstimateSync(true);activityBrowserMotionStop();post({action:'activityFinish',id:ending.id}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Activity could not finish.');var row=r.data.activity,ix=(TRAINING_FOUNDATION.activitySegments||[]).findIndex(function(x){return String(x.id)===String(row.id)});if(ix>=0)TRAINING_FOUNDATION.activitySegments[ix]=row;else TRAINING_FOUNDATION.activitySegments.unshift(row);activityBrowserCheckpointClear(ending);ACTIVE_ACTIVITY.row=null;ACTIVE_ACTIVITY.stepEstimator=null;activityTickStart();if(S.view==='movement')movementPage();myToast(activityTitleClient(row)+' finished and synced to MAH Calendar.')}).catch(function(e){myToast(e.message||'Activity could not finish.')}).finally(function(){ACTIVE_ACTIVITY.busy=false})}
function activityNativeMeasuredUpdate(metrics){metrics=metrics||{};if(!ACTIVE_ACTIVITY.row)return Promise.resolve(false);return post({action:'activityNativeUpdate',id:ACTIVE_ACTIVITY.row.id,metricSource:metrics.metricSource,steps:metrics.steps,distanceMi:metrics.distanceMi,activeEnergyKcal:metrics.activeEnergyKcal}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Measured Activity metrics could not update.');activityAdopt(r.data.activity);return true})}
window.MAHFITT_ACTIVITY_NATIVE_V1={version:1,updateMeasured:activityNativeMeasuredUpdate,getActive:function(){return trainingCopy(ACTIVE_ACTIVITY.row)},getLifecycleState:function(){return activityLifecycleState(ACTIVE_ACTIVITY.row)},requirements:{steps:'Core Motion / HealthKit measured source',distance:'Core Motion / HealthKit measured source',activeEnergy:'HealthKit measured source',dedupe:'source-aware aggregation; never blindly sum mirrored phone + Watch samples'}};
function movementSegmentHTML(s){if(!s||s.state!=='closed'||!s.ended_at)return'';var type=String(s.activity_type||'unclassified'),start=new Date(s.started_at),end=new Date(s.ended_at),minutes=Math.max(0,Math.round((end-start-Math.max(0,Number(s.paused_ms)||0))/60000)),measured=s.energy_source==='healthkit',label=type==='misc'?(s.activity_label||'Misc Activity'):type;return'<article class="movement-segment" data-id="'+h(s.id)+'"><header><div><span>'+h(start.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).toUpperCase())+'</span><b>'+h(String(label).toUpperCase())+'</b></div><label><span>RELABEL</span><select data-segment-type="'+h(s.id)+'">'+ACTIVITY_TYPES.map(function(t){return'<option value="'+t+'" '+(type===t?'selected':'')+'>'+h(activityTypeLabel(t))+'</option>'}).join('')+'<option value="workout" '+(type==='workout'?'selected':'')+'>WORKOUT</option><option value="unclassified" '+(type==='unclassified'?'selected':'')+'>UNCLASSIFIED</option></select></label></header><div class="movement-segment-metrics"><span><b>'+(s.steps==null?'—':Number(s.steps).toLocaleString('en-US'))+'</b>STEPS '+(activityMetricMeasured(s,'steps')?'MEASURED':'~')+'</span><span><b>'+(s.distance_mi==null?'—':Number(s.distance_mi).toFixed(2))+'</b>MI '+(activityMetricMeasured(s,'distance_mi')?'MEASURED':'')+'</span><span><b>'+(s.active_energy_kcal==null?'—':Math.round(Number(s.active_energy_kcal)))+'</b>KCAL '+(measured?'MEASURED':'~')+'</span><span><b>'+minutes+'</b>MIN</span></div><div class="movement-segment-actions"><label><input type="checkbox" data-segment-merge="'+h(s.id)+'"><span>SELECT TO MERGE</span></label><input type="datetime-local" data-segment-split="'+h(s.id)+'"><button data-a="activity-split" data-id="'+h(s.id)+'">SPLIT</button></div></article>'}
function movementPage(){S.view='movement';paintActivityMini();var m=movementLatestMetrics(),segments=(TRAINING_FOUNDATION.activitySegments||[]).filter(function(x){return x&&x.state==='closed'&&x.ended_at}),row=ACTIVE_ACTIVITY.row,kcal=activityLiveCalories(row),html=mahfittBannerHTML('ACTIVITY / PEDOMETER','movement','home','Back to MAH GYM','hd--progress')+mahfittPageContextHTML('ACTIVITY / PEDOMETER','progress-page-context')+'<main class="home movement-view"><div class="backbar"><button class="back" data-a="home">MAH GYM</button><span class="backbar__t">Live + recorded movement</span></div><section class="training-page-intro"><span>ACTIVITY / PEDOMETER</span><h1>START MOVING. MAHFITT KEEPS THE SESSION WITH YOU.</h1><p>Start a walk, run or other activity here. While it is active, the live mini-player follows you across MAHFITT so the timer does not disappear when you change pages.</p></section>'+trainingInlineStatusHTML('movement')+'<section class="activity-launch"><button class="is-primary" data-a="activity-new" data-type="walk">START WALK</button><div class="activity-launch-more">'+['run','cycling','hiking','fobbing','basketball','tennis','bouldering','misc'].map(function(t){return'<button data-a="activity-new" data-type="'+t+'">'+h(activityTypeLabel(t))+'</button>'}).join('')+'</div></section>'+activitySetupHTML()+(row?'<section class="activity-live-card"><header><span>LIVE · '+h(activityTitleClient(row))+'</span><b data-live-activity-time>'+activityDurationText(activityElapsedMs(row))+'</b></header><div><span>CALORIES</span><b data-live-activity-kcal>'+Math.round(kcal&&kcal.value||0)+' '+(kcal&&kcal.measured?'MEASURED':'~')+'</b></div>'+((row.activity_type==='walk'||row.activity_type==='run')?'<div><span>STEPS</span><b>'+(row.steps==null?'—':Number(row.steps).toLocaleString('en-US'))+' '+(row.steps==null?'':(activityMetricMeasured(row,'steps')?'MEASURED':'~'))+'</b></div>':'')+'<footer><button data-a="activity-'+(row.state==='paused'?'resume':'pause')+'">'+(row.state==='paused'?'RESUME':'PAUSE')+'</button>'+(((row.activity_type==='walk'||row.activity_type==='run')&&!ACTIVE_ACTIVITY.motionAllowed)?'<button data-a="activity-resume-sensor">RESUME STEP SENSOR</button>':'')+'<button data-a="activity-finish">FINISH</button></footer></section>':'')+'<section class="movement-primary"><div class="is-lead"><span>DISTANCE</span><b>'+(m.distance==null?'—':m.distance.toFixed(2)+' MI')+'</b></div><div class="is-second"><span>ACTIVE MINUTES</span><b>'+(m.activeMinutes==null?'—':Math.round(m.activeMinutes))+'</b></div><div class="is-support"><span>STEPS</span><b>'+(m.steps==null?'—':m.steps.toLocaleString('en-US'))+'</b></div><div class="is-support"><span>ACTIVE ENERGY</span><b>'+(m.kcal==null?'—':Math.round(m.kcal)+' KCAL')+'</b><small>'+(m.kcal==null?'NO DEVICE ENERGY DATA':'MEASURED · DEVICE / HEALTH')+'</small></div></section><p class="movement-source-note">MEASURED means a device / HealthKit / Core Motion source supplied the value. A tilde (~) means MAHFITT estimated it. Browser-estimated steps are cadence-filtered and only run while MAHFITT is active in the foreground; if iOS suspends or closes the app, reopen the active Walk/Run and tap RESUME STEP SENSOR. The last foreground checkpoint is preserved. The browser will not pretend estimated steps or distance are Apple Watch measurements.</p><div class="movement-list">'+(segments.length?segments.map(movementSegmentHTML).join(''):'<div class="movement-empty"><b>NO COMPLETED ACTIVITIES YET</b><p>Start a Walk, Run, or Misc Activity above. Native HealthKit / Watch sources can later enrich the same canonical records.</p></div>')+'</div>'+(segments.length?'<button class="mg-button movement-merge" data-a="activity-merge">MERGE SELECTED SEGMENTS</button>':'')+'<section class="movement-health-optin"><header>OPTIONAL</header><button class="mg-button movement-watch" data-a="health"><span><b>CONNECT APPLE HEALTH</b><small>Optional. Uses measured Apple Health data instead of estimates.</small></span><i>›</i></button></section></main>';root.innerHTML=html;bindTempoControl();paintTempoControl()}
function editActivityRelabel(id,type){var label=type==='misc'?'Misc Activity':'';post({action:'activitySegmentEdit',op:'relabel',id:id,activityType:type,activityLabel:label}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Activity could not update.');return post({action:'trainingFoundation'})}).then(function(r){if(r.data&&r.data.ok)trainingFoundationApply(r.data);movementPage();myToast('Activity relabeled and Calendar correlation updated.')}).catch(function(e){myToast(e.message||'Activity could not update.')})}
