function healthValue(def,v){if(v==null||!Number.isFinite(Number(v)))return'<b>—</b><small>'+h(def.unit||'')+'</small>';v=Number(v);if(def.sleep){var hr=Math.floor(v/60),mn=Math.round(v%60);return'<b>'+hr+'H '+String(mn).padStart(2,'0')+'M</b><small>SLEEP</small>'}var dec=def.dec==null?0:def.dec,n=v.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});return'<b>'+h(n)+'</b><small>'+h(def.unit||'')+'</small>'}
