function healthSeries(key,range){var rows=(HEALTH_UI.days||[]).slice().sort(function(a,b){return a.day<b.day?-1:a.day>b.day?1:0}),max=rows.length?rows[rows.length-1].day:'',cut=max?healthDayOffset(max,-Math.max(0,range-1)):'';return rows.filter(function(r){return!cut||r.day>=cut}).map(function(r){var v=r.metrics&&r.metrics[key];return v==null?null:{day:r.day,value:Number(v)}}).filter(Boolean).filter(function(x){return Number.isFinite(x.value)})}
