function paintHealthTrendSelection(){if(S.view!=='health')return;var def=healthMetric(HEALTH_UI.metric),title=root.querySelector('.mah-health-trend>header>div>b'),chart=root.querySelector('.mah-health-chart');if(title)title.textContent=def.label;if(chart)chart.innerHTML=healthChartSVG(def.key,HEALTH_UI.range);root.querySelectorAll('[data-a="health-metric"]').forEach(function(b){var on=b.dataset.m===def.key;b.dataset.on=on?'1':'0';b.setAttribute('aria-pressed',on?'true':'false')});root.querySelectorAll('[data-a="health-range"]').forEach(function(b){var on=+b.dataset.n===HEALTH_UI.range;b.dataset.on=on?'1':'0';b.setAttribute('aria-pressed',on?'true':'false')})}
function healthConnectionPanel(){var st=HEALTH_UI.status||{},unknown=!HEALTH_UI.loaded&&!!(HEALTH_UI.offline||HEALTH_UI.error),connected=!unknown&&!!st.connected,last=st.lastUsedAt||null,state=unknown?'STATUS UNKNOWN':connected?'CONNECTED':'NOT CONNECTED',sub=unknown?'CONNECTION UNAVAILABLE':connected?(last?('LAST SHORTCUT SYNC · '+h(healthTime(last))):'SHORTCUT NOT RUN YET'):'ZERO-COST SHORTCUT CONNECTION';return'<section class="mah-health-connect" data-connected="'+(connected?'1':'0')+'" data-unknown="'+(unknown?'1':'0')+'"><div class="mah-health-connect__mark"><i></i><span>APPLE HEALTH BRIDGE</span></div><div class="mah-health-connect__state"><b>'+state+'</b><small>'+sub+'</small></div><button data-a="health-setup">'+(connected?'SYNC SETUP':unknown?'SETUP':'CONNECT')+'</button></section>'}
