function mahHealth(){S.view='health';var latest=healthLatestDay(),metrics=latest&&latest.metrics||{},html=mahfittBannerHTML('MAH HEALTH','health','home','Back to MAH GYM','hd--health')+mahfittPageContextHTML('MAH HEALTH','mah-health-page-context')+'<main class="mah-health-view"><div class="mah-health-backbar"><button data-a="home">← MAH GYM</button><span>'+(HEALTH_UI.offline?'OFFLINE · SHOWING LAST LOADED DATA':latest?('LATEST · '+h(healthDateLabel(latest.day))):'APPLE HEALTH + MAHFITT')+'</span><button data-a="health-refresh" aria-label="Refresh health data" aria-busy="'+(HEALTH_UI.busy?'true':'false')+'" '+(HEALTH_UI.busy?'disabled':'')+'>↻</button></div>'+healthConnectionPanel()+'<button class="mah-watch-entry" data-a="watch-open"><span class="mah-watch-entry__icon" aria-hidden="true">▣</span><span><b>APPLE WATCH</b><small>CONNECTION · STATUS · HEALTH FOUNDATION</small></span><i aria-hidden="true">›</i></button>';
if(latest){if(HEALTH_UI.error)html+='<div class="mah-health-alert">'+h(HEALTH_UI.error)+'</div>';html+='<section class="mah-health-metrics" aria-label="Latest health metrics">'+HEALTH_METRICS.map(function(def){var on=HEALTH_UI.metric===def.key;return'<button class="mah-health-metric" data-a="health-metric" data-m="'+def.key+'" data-on="'+(on?'1':'0')+'" aria-pressed="'+(on?'true':'false')+'"><span>'+h(def.label)+'</span><div>'+healthValue(def,metrics[def.key])+'</div></button>'}).join('')+'</section><section class="mah-health-trend"><header><div><span>TREND</span><b>'+h(healthMetric(HEALTH_UI.metric).label)+'</b></div><div class="mah-health-ranges">'+[7,30,90].map(function(n){return'<button data-a="health-range" data-n="'+n+'" data-on="'+(HEALTH_UI.range===n?'1':'0')+'" aria-pressed="'+(HEALTH_UI.range===n?'true':'false')+'">'+n+'D</button>'}).join('')+'</div></header><div class="mah-health-chart">'+healthChartSVG(HEALTH_UI.metric,HEALTH_UI.range)+'</div></section>'}else html+=healthEmptyHTML();
html+='<section class="mah-health-history"><div><span>HISTORY</span><b>APPLE HEALTH EXPORT</b><p>Import your old Health history without uploading the raw export file. MAHFITT reads it on this device and sends only daily summaries.</p></div><button data-a="health-import">IMPORT HISTORY</button></section><p class="mah-health-privacy">RAW APPLE HEALTH EXPORT FILES STAY ON THIS DEVICE · MAHFITT STORES DAILY SUMMARY METRICS ONLY</p></main>';root.innerHTML=html;bindTempoControl();paintTempoControl()}
function clearHealthAbort(ref){if(!ref)return;if(ref.timer)clearTimeout(ref.timer);try{if(ref.controller&&!ref.controller.signal.aborted)ref.controller.abort()}catch(e){}}
function makeHealthAbort(ms){var c=typeof AbortController!=='undefined'?new AbortController():null,ref={controller:c,timer:0};if(c&&ms)ref.timer=setTimeout(function(){try{c.abort()}catch(e){}},ms);return ref}
