function copyText(text){text=String(text||'');if(navigator.clipboard&&navigator.clipboard.writeText)return navigator.clipboard.writeText(text).catch(function(){return fallback()});return fallback();function fallback(){return new Promise(function(resolve,reject){try{var ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();var ok=document.execCommand('copy');ta.remove();if(ok)resolve();else reject(new Error('copy failed'))}catch(e){reject(e)}})}}
