function healthEnsureKey(){if(HEALTH_UI.keyBusy)return;var req=++HEALTH_CRED_REQ;HEALTH_UI.keyBusy=true;paintHealthDialog();var dialog=document.getElementById('mahHealthDialog'),stamp=dialog;healthCredentialPost({action:'healthSyncToken'}).then(function(r){if(req!==HEALTH_CRED_REQ||document.getElementById('mahHealthDialog')!==stamp)return;if(!r.data||!r.data.ok||!r.data.token)throw new Error(r.data&&r.data.error||'Health key could not be created.');var token=r.data.token;HEALTH_UI.status=Object.assign({},HEALTH_UI.status||{},{connected:true,createdAt:r.data.createdAt,lastUsedAt:r.data.lastUsedAt});return copyText(token).then(function(){HEALTH_UI.key='';myToast('Health Sync key copied.')}).catch(function(){HEALTH_UI.key=token;myToast('Key ready. Press and hold it to copy manually.')})}).catch(function(e){myToast(e.message||'Health key could not be created.')}).finally(function(){if(req!==HEALTH_CRED_REQ)return;HEALTH_UI.keyBusy=false;if(document.getElementById('mahHealthDialog')===stamp)paintHealthDialog();if(S.view==='health')mahHealth()})}
