function handleHealthOverlayAction(b){if(!b)return false;var a=b.dataset.a;if(a==='health-dialog-close'){closeHealthDialog();return true}if(a==='health-copy-endpoint'){copyText(healthEndpoint()).then(function(){myToast('Health endpoint copied.')}).catch(function(){myToast('Could not copy automatically.')});return true}if(a==='health-key'){healthEnsureKey();return true}if(a==='health-revoke'){healthRevoke();return true}if(a==='health-run-shortcut'){healthRunShortcut();return true}if(a==='health-import-close'){closeHealthImport();return true}if(a==='health-file'){var input=document.getElementById('mahHealthFile');if(input)input.click();return true}if(a==='health-import-commit'){commitHealthImport(false);return true}if(a==='health-import-retry'){commitHealthImport(true);return true}return false}
