function mapMemberProgramRows(rows){return(rows||[]).map(function(x){var b=x.body&&typeof x.body==='object'?x.body:{};b.dbId=x.id;b._compat=!!x.compat;b._updatedAt=x.updated_at||'';b.name=b.name||x.name||'Program';b.sub=b.sub||x.sub||((b.days||[]).length+' workouts');return b})}
function isMemberOwnedProgram(p){return!!(p&&p._memberProgram===MEMBER_PROGRAM_MARK&&!p._compat)}
function refreshMemberPrograms(){return post({action:'memberPrograms'}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Programs could not refresh.');S.programs=mapMemberProgramRows(r.data.programs||[]);return S.programs})}
function memberPreset(id){return MEMBER_PRESETS.find(function(p){return p.id===id})||null}
/* v400 A2 + Group B. The old header was a single row of
   52px | 1fr | 106px with the mark pinned to the end, so on a 390px
   viewport the brand ran into the frame's right padding and clipped. It
   also had no Player/Theme entry at all, which made Program Library the
   only member surface where those controls were unreachable.
   Now a compact two-row pseudo-banner in My Gym's language: identity row,
   then the SHARED themeControls() cluster. Those controls route through the
   same data-a handlers as everywhere else -- openMusicStudio/openThemeEditor
   -- so they open as overlays over the library and return to it on close.
   No second audio engine, no navigation, no duplicated Theme editor. */
function programLibraryHeader(title){return mahfittBannerHTML(title||'PROGRAM LIBRARY','programlib','home','Back to MAH GYM','programlib-hd programlib-hd--v400 programlib-hd--v401')
  +'<div class="mf-banner__context programlib-hd__context"><button class="programlib-back mf-back-control" data-a="program-library-back" aria-label="Back to MAH GYM"><span class="mf-back-arrow" aria-hidden="true"></span></button><span>'+h(title||'PROGRAM LIBRARY')+'</span>'+mahfittClientContextHTML()+'<time>'+today()+'</time></div>'}

function programLibrary(){S.view='program-library';var client=isCoachClientContext(),mine=client?S.programs.slice():S.programs.filter(isMemberOwnedProgram),coach=client?[]:S.programs.filter(function(p){return!isMemberOwnedProgram(p)});var html=programLibraryHeader('PROGRAM LIBRARY')+'<main class="programlib"><div class="programlib-intro"><span>'+(client?'AUTHORIZED CLIENT PROGRAMMING':'BUILD YOUR TRAINING')+'</span><h2>Choose a structure or make your own.</h2><p>'+(client?'Changes here write to '+h(S.member.name)+'\'s canonical Program Library.':'Your programs are editable here. Programs assigned by your coach stay protected.')+'</p><button class="programlib-create" data-a="program-create">＋ CREATE PROGRAM</button>'+(client?'<button class="programlib-retrowork is-protected" data-a="mahfitt-ai"><span>AI PROWORK</span><small>PRIVATE TO '+h(S.member.name).toUpperCase()+'</small></button>':'<button class="programlib-retrowork" data-a="prowork-open"><span>AI PROWORK</span><small>BUILD A PROGRAM BY VOICE OR TEXT</small></button>')+'</div>'+(client?'<section class="programlib-coach-tools"><header><span>PROGRAM TOOLS</span><small>OPEN ONLY WHEN YOU NEED THE MACHINERY</small></header><button class="ghost" data-a="coach-periodization">PERIODIZATION</button><button class="ghost" data-a="program-create">ROUTINE / PROGRAM CREATOR</button><button class="ghost" data-a="coach-exercises">EXERCISE DATABASE</button><button class="ghost" data-a="progress">BODY / ACTIVITY</button></section>':'')+programSearchHTML()+motionDivider();
if(mine.length){html+='<section class="programlib-section"><header><span>'+(client?'CLIENT PROGRAMS':'YOUR PROGRAMS')+'</span><b>'+mine.length+'</b></header>'+mine.map(function(p){return'<article class="programlib-card programlib-card--mine"><div><b>'+h(p.name)+'</b><span>'+h(p.sub||((p.days||[]).length+' workouts'))+'</span></div><button data-a="program-edit" data-id="'+h(p.dbId)+'">EDIT</button></article>'}).join('')+'</section>'}
if(coach.length){html+='<section class="programlib-section"><header><span>COACH PROGRAMS</span><b>'+coach.length+'</b></header>'+coach.map(function(p){return'<article class="programlib-card programlib-card--coach"><div><b>'+h(p.name)+'</b><span>'+h(p.sub||((p.days||[]).length+' workouts'))+'</span></div><em>READ ONLY</em></article>'}).join('')+'</section>'}
html+='<section class="programlib-section programlib-presets"><header><span>PROGRAM STRUCTURES</span><b>'+MEMBER_PRESETS.length+'</b></header>'+MEMBER_PRESETS.map(function(p){return'<article class="programlib-card"><div><b>'+h(p.name)+'</b><span>'+h(p.sub)+'</span></div><button data-a="program-preset-add" data-id="'+p.id+'">＋ ADD</button></article>'}).join('')+'</section></main>';root.innerHTML=html;bindTempoControl();paintTempoControl();bindProgramSearch();applyProgramSearch('')}

/* v441 §25-27 — PROGRAM SEARCH.
   Canonical filtering did not exist: programLibrary() rendered every list
   unconditionally and nothing read user input, so finding a structure meant
   scanning 12+ cards by hand. This is the smallest thing that works: one
   LABELLED field (not an unexplained icon), a live client-side filter over the
   cards already in the DOM, a reset, and a no-results state. It never
   re-renders the page, so member-edit vs coach READ ONLY, workout counts,
   metadata and every existing data-a action survive untouched -- cards are only
   shown or hidden. */
function programSearchHTML(){
  return'<div class="programlib-search" role="search">'
    +'<label class="programlib-search__label" for="programSearchInput">SEARCH PROGRAMS</label>'
    +'<div class="programlib-search__row">'
    +'<input id="programSearchInput" class="programlib-search__input" type="search" autocomplete="off" autocapitalize="none" spellcheck="false" enterkeyhint="search" placeholder="Program name" data-a="program-search" aria-label="Search programs by name">'
    +'<button type="button" class="programlib-search__clear" data-a="program-search-clear" aria-label="Clear program search" hidden>CLEAR</button>'
    +'</div>'
    +'<p class="programlib-search__empty" data-program-search-empty hidden>NO PROGRAMS MATCH THAT NAME.</p>'
    +'</div>';
}
function programSearchCardName(card){
  var b=card.querySelector('b');
  return String((b&&b.textContent)||card.textContent||'').toLowerCase();
}
function applyProgramSearch(raw){
  var root=document.querySelector('#mygym .programlib');if(!root)return 0;
  var q=String(raw==null?'':raw).trim().toLowerCase();
  var shown=0;
  root.querySelectorAll('.programlib-card').forEach(function(card){
    var hit=!q||programSearchCardName(card).indexOf(q)>=0;
    card.hidden=!hit;if(hit)shown++;
  });
  /* A section whose cards are all filtered out hides its heading too, so the
     count in a header can never contradict what is on screen. */
  root.querySelectorAll('.programlib-section').forEach(function(sec){
    sec.hidden=!!q&&!sec.querySelector('.programlib-card:not([hidden])');
  });
  var empty=root.querySelector('[data-program-search-empty]');
  if(empty)empty.hidden=!(q&&shown===0);
  var clear=root.querySelector('.programlib-search__clear');
  if(clear)clear.hidden=!q;
  return shown;
}
function bindProgramSearch(){
  var input=document.getElementById('programSearchInput');
  if(!input||input.dataset.bound==='1')return;
  input.dataset.bound='1';
  input.addEventListener('input',function(){applyProgramSearch(input.value)});
  input.addEventListener('search',function(){applyProgramSearch(input.value)});
  input.addEventListener('keydown',function(e){if(e.key==='Escape'){input.value='';applyProgramSearch('');input.blur()}});
  /* Bound directly rather than through an action router: the music router that
     owns most data-a strings never runs on the Program Library route, so a
     routed CLEAR silently did nothing. Measured: clear left 0 cards visible. */
  var clear=document.querySelector('#mygym .programlib-search__clear');
  if(clear&&clear.dataset.bound!=='1'){
    clear.dataset.bound='1';
    clear.addEventListener('click',function(e){
      e.preventDefault();e.stopPropagation();
      input.value='';applyProgramSearch('');input.focus();
    });
  }
}

