function guidedCatalog(role){var out=OUTDOOR_GUIDE_CATALOG.filter(function(x){return x.role===role||(role==='main'&&['performance_indicator','compound','accessory','isolation_or_targeted'].indexOf(x.role)>=0)});if(GUIDED_BUILDER&&GUIDED_BUILDER.workoutType!=='outdoor'){var extras=role==='main'?['Bench Press','Back Squat','Barbell Row','Romanian Deadlift','Overhead Press','Lat Pulldown','Dumbbell Curl','Cable Triceps Pressdown']:role==='warmup'?['Easy Push-Up','Bodyweight Squat','Arm Circles','Walking Lunge']:role==='mobility'?['Hip Flexor Mobility','Chest / Shoulder Mobility']:['Easy Walk','Easy Cycling'];extras.forEach(function(n){out.push({name:n,role:role==='main'?'compound':role,dynamic:role==='warmup'})})}return out}
function guidedHas(name,list){return(list||[]).some(function(x){return x.name===name})}
function guidedToggle(name,role,dynamic){if(!GUIDED_BUILDER)return;var list=role==='warmup'?GUIDED_BUILDER.warmup:role==='mobility'?GUIDED_BUILDER.mobility:GUIDED_BUILDER.main,idx=list.findIndex(function(x){return x.name===name});if(idx>=0)list.splice(idx,1);else{var meta=OUTDOOR_GUIDE_CATALOG.find(function(x){return x.name===name&&((role==='main'&&['performance_indicator','compound','accessory','isolation_or_targeted'].indexOf(x.role)>=0)||x.role===role)});list.push({name:name,role:meta&&meta.role||role,dynamic:!!(meta&&meta.dynamic||dynamic),target:meta&&meta.target||'full'})}paintGuidedBuilder()}
function guidedValidation(step){var g=GUIDED_BUILDER;if(!g)return'';if(step===2){if(g.warmup.length<2)return'Add at least two warm-up items.';var dyn=g.warmup.filter(function(x){return x.dynamic});if(!dyn.length)return'Add one moving warm-up. Two static stretches do not prepare the workout.';var lower=/lower|leg/i.test(g.purpose),upper=/upper/i.test(g.purpose),relevant=dyn.some(function(x){return x.target==='full'||x.target==='conditioning'||(lower&&x.target==='lower')||(upper&&x.target==='upper')||(!lower&&!upper)});if(!relevant)return lower?'Add one moving warm-up for your legs before this lower-body workout.':'Add one moving warm-up that matches the muscles you are about to train.'}if(step===3&&!g.main.length)return'Add at least one main training movement.';if(step===5&&g.cooldownSeconds<180)return'Easy cardio cooldown must be at least 3 minutes in Guided Builder.';return''}
function guidedContextHint(){if(!PROGRAM_DRAFT)return'';var counts={upper:0,lower:0};(PROGRAM_DRAFT.days||[]).forEach(function(d,i){if(GUIDED_BUILDER&&i===GUIDED_BUILDER.dayIndex)return;var n=String(d.name||d.purpose||'').toLowerCase();if(/upper|push|pull|chest|back/.test(n))counts.upper++;if(/lower|leg|squat/.test(n))counts.lower++});if(counts.upper>=2&&counts.lower===0)return'This program already has a lot of upper-body work. A lower-body or full-body day may balance it better.';if(counts.lower>=2&&counts.upper===0)return'This program already has a lot of lower-body work. An upper-body or full-body day may balance it better.';return''}
function guidedChoiceButtons(role,list){return guidedCatalog(role).slice(0,18).map(function(x){var on=guidedHas(x.name,list);return'<button type="button" class="guided-choice" data-a="guided-toggle" data-role="'+role+'" data-name="'+h(x.name)+'" data-dynamic="'+(x.dynamic?'1':'0')+'" data-on="'+(on?'1':'0')+'">'+h(x.name)+(x.dynamic&&role==='warmup'?'<small>DYNAMIC</small>':'')+'</button>'}).join('')}
function guidedReviewHTML(g){var perf=g.main.find(function(x){return x.role==='performance_indicator'})||g.main[0];return'<div class="guided-review"><section><span>PURPOSE</span><b>'+h(g.purpose||'General fitness')+'</b></section><section><span>WARM-UP</span>'+g.warmup.map(function(x,i){return'<p>'+(i+1)+'. '+h(x.name)+(x.dynamic?' · DYNAMIC':'')+'</p>'}).join('')+'</section><section><span>MAIN MOVEMENT</span><b>'+h(perf&&perf.name||'Choose one')+'</b><small>One big movement that tells you whether you are getting better.</small></section><section><span>ACCESSORIES / TARGETED WORK</span>'+g.main.filter(function(x){return !perf||x.name!==perf.name}).map(function(x){return'<p>'+h(x.name)+'</p>'}).join('')+'</section><section><span>STRETCH / MOBILITY</span>'+g.mobility.map(function(x){return'<p>'+h(x.name)+'</p>'}).join('')+'</section><section><span>CARDIO COOLDOWN</span><b>'+h(g.cooldownName)+' · '+Math.round(g.cooldownSeconds/60)+' MIN</b></section><div class="guided-structure-check"><b>STRUCTURE CHECK</b><p>✓ '+g.warmup.length+' warm-up items</p><p>✓ dynamic movement included</p><p>✓ '+g.main.length+' main exercise'+(g.main.length===1?'':'s')+'</p><p>✓ performance indicator '+(perf?'chosen':'needed')+'</p><p>✓ '+Math.round(g.cooldownSeconds/60)+' min easy cooldown</p></div></div>'}
function guidedStepHTML(g){var hint=guidedContextHint();if(g.step===0)return'<span>WORKOUT TYPE</span><h2>WHAT KIND OF WORKOUT ARE YOU BUILDING?</h2><p>Outdoor keeps exercise choices realistic for a park, field, track, or open space.</p><div class="guided-purpose"><button data-a="guided-workout-type" data-type="regular" data-on="'+(g.workoutType==='regular'?'1':'0')+'">REGULAR WORKOUT</button><button data-a="guided-workout-type" data-type="outdoor" data-on="'+(g.workoutType==='outdoor'?'1':'0')+'">OUTDOOR WORKOUT</button></div>';if(g.step===1)return'<span>1 · WORKOUT PURPOSE</span><h2>WHAT IS THIS WORKOUT MAINLY FOR?</h2>'+(hint?'<p class="guided-hint">'+h(hint)+'</p>':'')+'<div class="guided-purpose">'+guidedPurposeOptions().map(function(x){return'<button data-a="guided-purpose" data-purpose="'+h(x)+'" data-on="'+(g.purpose===x?'1':'0')+'">'+h(x)+'</button>'}).join('')+'</div><p class="guided-teach"><b>PERFORMANCE INDICATOR</b> Pick one big movement that tells you whether you are actually getting better. Accessories help that movement and train what it misses.</p>';
if(g.step===2)return'<span>2 · WARM-UP</span><h2>GET MOVING FIRST</h2><p>Your warm-up should raise your temperature and prepare the muscles you are about to use.</p><div class="guided-choices">'+guidedChoiceButtons('warmup',g.warmup)+'</div><small>Need at least 2 items, including 1 dynamic movement.</small>';
if(g.step===3)return'<span>3 · MAIN WORK</span><h2>BUILD THE WORKOUT</h2><p>Start with one big performance indicator, then add support work. For a normal strength workout, 4–8 exercises is a useful target—not a prison.</p><div class="guided-choices">'+guidedChoiceButtons('main',g.main)+'</div>'+(g.main.length&& (g.main.length<4||g.main.length>8)?'<p class="guided-soft">You have '+g.main.length+' main exercises. Most standard workouts land around 4–8.</p>':'');
if(g.step===4)return'<span>4 · STRETCH / MOBILITY</span><h2>KEEP IT SHORT</h2><p>Use a short stretch or mobility drill for the areas you just trained.</p><div class="guided-choices">'+guidedChoiceButtons('mobility',g.mobility)+'</div><small>1–2 is usually enough.</small>';
if(g.step===5)return'<span>5 · CARDIO COOLDOWN</span><h2>COME DOWN GRADUALLY</h2><p>Finish with easy movement so your body can gradually come down from hard work.</p><label><span>EASY MOVEMENT</span><select data-guided-cooldown-name><option>Easy Walk</option><option>Very Easy Jog</option><option>Easy Cycling</option></select></label><label><span>MINUTES</span><input data-guided-cooldown-min type="number" min="0" max="60" value="'+Math.round(g.cooldownSeconds/60)+'"></label><small>Guided Builder requires at least 3 minutes.</small>';
return'<span>6 · REVIEW</span><h2>YOUR WORKOUT STRUCTURE</h2>'+guidedReviewHTML(g)}
function paintGuidedBuilder(){var m=document.getElementById('guidedWorkoutBuilder'),g=GUIDED_BUILDER;if(!m||!g)return;var body=m.querySelector('.guided-builder-body');body.innerHTML=guidedStepHTML(g)+(g.error?'<div class="guided-error">'+h(g.error)+'</div>':'')+'<footer><button data-a="guided-back" '+(g.step<=0?'disabled':'')+'>BACK</button><button class="is-primary" data-a="guided-next">'+(g.step>=6?'SAVE WORKOUT':'CONTINUE')+'</button></footer>';var sel=body.querySelector('[data-guided-cooldown-name]');if(sel)sel.value=g.cooldownName}
function openGuidedBuilder(dayIndex){if(!PROGRAM_DRAFT)return;GUIDED_BUILDER=guidedFresh(dayIndex);var old=document.getElementById('guidedWorkoutBuilder');if(old)old.remove();var m=document.createElement('section');m.id='guidedWorkoutBuilder';m.className='guided-builder-overlay';m.innerHTML='<button class="guided-builder-backdrop" data-a="guided-close" aria-label="Close"></button><article class="guided-builder-card" role="dialog" aria-modal="true"><header><span>GUIDED WORKOUT BUILDER</span><button data-a="guided-close" aria-label="Close">×</button></header><div class="guided-builder-body"></div></article>';document.body.appendChild(m);document.body.classList.add('guided-builder-open');syncMahfittOverlayOwnership();paintGuidedBuilder()}
function closeGuidedBuilder(){var m=document.getElementById('guidedWorkoutBuilder');if(m)m.remove();document.body.classList.remove('guided-builder-open');GUIDED_BUILDER=null;syncMahfittOverlayOwnership()}
function guidedAdvance(){var g=GUIDED_BUILDER;if(!g)return;if(g.step===0&&!g.workoutType){g.error='Choose Regular Workout or Outdoor Workout.';return paintGuidedBuilder()}if(g.step===1&&!g.purpose){g.error='Choose the main job for this workout.';return paintGuidedBuilder()}var err=guidedValidation(g.step);if(err){g.error=err;return paintGuidedBuilder()}g.error='';if(g.step<6){g.step++;return paintGuidedBuilder()}var perf=g.main.find(function(x){return x.role==='performance_indicator'});if(!perf&&g.main[0])g.main[0].role='performance_indicator';var items=g.warmup.map(function(x){return guidedItem(x.name,'warmup',x.dynamic)}).concat(g.main.map(function(x){return guidedItem(x.name,x.role||'compound',false)}),g.mobility.map(function(x){return guidedItem(x.name,'mobility',false)}),[guidedItem(g.cooldownName,'cooldown',false)]);var cool=items[items.length-1];if(cool&&cool.exerciseRole==='cooldown'&&cool.sets&&cool.sets[0])cool.sets[0].time=g.cooldownSeconds;var day={name:g.purpose||('Workout '+(g.dayIndex+1)),workoutType:g.workoutType,purpose:g.purpose,guidedBuilder:true,cooldownDurationSeconds:g.cooldownSeconds,items:items};if(PROGRAM_DRAFT.days[g.dayIndex])PROGRAM_DRAFT.days[g.dayIndex]=day;else PROGRAM_DRAFT.days.push(day);closeGuidedBuilder();renderProgramEditor();myToast('Guided workout added.')}
function guidedBack(){if(GUIDED_BUILDER&&GUIDED_BUILDER.step>1){GUIDED_BUILDER.step--;GUIDED_BUILDER.error='';paintGuidedBuilder()}}
function cleanProgramDraft(raw){raw=clone(raw||{});raw.name=String(raw.name||'My Program');raw.sub=String(raw.sub||'');raw.programType=raw.programType==='outdoor'?'outdoor':'regular';raw.days=Array.isArray(raw.days)?raw.days:[];if(!raw.days.length)raw.days=[{name:'Workout 1',workoutType:raw.programType,items:[]}];raw.days.forEach(function(d){d.workoutType=raw.programType==='outdoor'?'outdoor':(d.workoutType==='outdoor'?'outdoor':'regular');d.cooldownDurationSeconds=Math.max(0,Number(d.cooldownDurationSeconds)||0)});raw._memberProgram=MEMBER_PROGRAM_MARK;return raw}
function openProgramEditor(program){PROGRAM_DRAFT=cleanProgramDraft(program||{name:'My Program',sub:'',days:[{name:'Workout 1',items:[]}]});S.view='program-editor';renderProgramEditor()}
function renderProgramEditor(){if(!PROGRAM_DRAFT)return programLibrary();var p=PROGRAM_DRAFT,html=programLibraryHeader('EDIT PROGRAM')+'<main class="programedit"><section class="programedit-title"><div class="programedit-type"><span>PROGRAM TYPE</span><b>'+h(programTypeOf(p).toUpperCase())+'</b><small>'+(programTypeOf(p)==='outdoor'?'OUTDOOR-ONLY EXERCISE DISCOVERY':'REGULAR EXERCISE LIBRARY')+'</small></div><label><span>PROGRAM NAME</span><input data-program-field="name" maxlength="80" value="'+h(p.name)+'"></label><label><span>DESCRIPTION</span><input data-program-field="sub" maxlength="140" value="'+h(p.sub||'')+'" placeholder="3 days · full body"></label></section>'+motionDivider();
p.days.forEach(function(day,di){html+='<section class="programedit-day" data-day="'+di+'"><header><label><span>DAY '+(di+1)+' · '+h((day.workoutType||programTypeOf(p)).toUpperCase())+'</span><input data-program-day-name="'+di+'" maxlength="80" value="'+h(day.name||('Workout '+(di+1)))+'"></label><button data-a="program-day-remove" data-day="'+di+'" '+(p.days.length<2?'disabled':'')+'>×</button></header><div class="programedit-items">'+((day.items||[]).length?(day.items||[]).map(function(it,ii){return'<article class="programedit-item"><div><b>'+h(it.name||'Exercise')+'</b><span>'+h((it.vars||['weight','reps']).join(' + '))+'</span></div><label><span>SETS</span><input type="number" min="1" max="12" inputmode="numeric" data-program-sets="'+di+':'+ii+'" value="'+Math.max(1,(it.sets||[]).length||3)+'"></label><button data-a="program-exercise-remove" data-day="'+di+'" data-item="'+ii+'" aria-label="Remove '+h(it.name||'exercise')+'">×</button></article>'}).join(''):'<div class="programedit-empty">No exercises yet.</div>')+'</div><button class="programedit-addex" data-a="program-exercise-add" data-day="'+di+'">＋ ADD EXERCISE</button></section>'});
html+='<div class="programedit-addworkout"><div class="programedit-modeswitch" role="group" aria-label="Workout builder mode"><span>BUILDER MODE</span><button type="button" class="programedit-mode" data-a="program-builder-mode" data-mode="guided" data-on="'+(programBuilderMode()==='guided'?'1':'0')+'" aria-pressed="'+(programBuilderMode()==='guided'?'true':'false')+'">GUIDED</button><button type="button" class="programedit-mode" data-a="program-builder-mode" data-mode="direct" data-on="'+(programBuilderMode()==='direct'?'1':'0')+'" aria-pressed="'+(programBuilderMode()==='direct'?'true':'false')+'">DIRECT</button></div><button class="programedit-addday is-guided" data-a="program-add-workout">＋ ADD WORKOUT</button><small>'+(programBuilderMode()==='guided'?'Guided walks warm-up → main → mobility → cooldown → review, one step at a time.':'Direct adds an empty workout you fill in yourself.')+'</small></div><button class="programlib-retrowork programedit-program-creator" data-a="prowork-program-edit"><span>AI PROWORK</span><small>BUILD FUTURE PROGRAMMING AS A REVIEWABLE DRAFT</small></button><div class="programedit-actions"><button data-a="program-editor-cancel">CANCEL</button><button class="is-primary" data-a="program-save">SAVE PROGRAM</button></div>'+(p.dbId?'<button class="programedit-delete" data-a="program-delete">REMOVE MY PROGRAM</button>':'')+'</main>';root.innerHTML=html;bindTempoControl();paintTempoControl()}
function blankProgramSet(vars){return setFromVars(vars||['weight','reps'],{})}
function setProgramItemCount(item,count){count=Math.max(1,Math.min(12,parseInt(count,10)||1));item.vars=cleanExerciseVars(item.vars);item.sets=Array.isArray(item.sets)?item.sets:[];while(item.sets.length<count)item.sets.push(blankProgramSet(item.vars));if(item.sets.length>count)item.sets=item.sets.slice(0,count)}
function programFieldInput(t){if(!PROGRAM_DRAFT)return;if(t.dataset.programField){PROGRAM_DRAFT[t.dataset.programField]=t.value;return}if(t.dataset.programDayName!=null){var di=+t.dataset.programDayName;if(PROGRAM_DRAFT.days[di])PROGRAM_DRAFT.days[di].name=t.value;return}if(t.dataset.programSets){var bits=t.dataset.programSets.split(':'),day=PROGRAM_DRAFT.days[+bits[0]],item=day&&day.items&&day.items[+bits[1]];if(item)setProgramItemCount(item,t.value)}}
function memberProgramExercise(ex){var it=memberExerciseFromLibrary(ex,'main');it.sets=it.sets.slice(0,3);return it}
function outdoorExerciseCompatible(ex){var n=String(ex&&ex.name||'').toLowerCase();if(!n)return false;if(/machine|cable|leg press|hack squat|treadmill|smith|pec deck|pulldown|selectorized/.test(n))return false;return /pull[- ]?up|chin[- ]?up|push[- ]?up|dip|squat|lunge|split squat|step[- ]?up|calf raise|plank|leg raise|knee raise|mountain climber|bear crawl|sprint|run|jog|walk|jump|bound|burpee|a-skip|high knee|arm circle|leg swing|glute bridge|nordic|copenhagen|inverted row|bodyweight|mobility|stretch/.test(n)}
function closeProgramExercisePicker(){var x=document.getElementById('memberProgramPicker');if(x)x.remove();document.body.classList.remove('program-picker-open');syncMahfittOverlayOwnership()}
function openProgramExercisePicker(dayIndex){if(!PROGRAM_DRAFT||!PROGRAM_DRAFT.days[dayIndex])return;closeProgramExercisePicker();var m=document.createElement('section');m.id='memberProgramPicker';m.className='program-picker';m.innerHTML='<button class="program-picker__back" data-program-picker-close aria-label="Close exercise picker"></button><div class="program-picker__card" role="dialog" aria-modal="true"><header><div><span>PROGRAM LIBRARY</span><h2>ADD EXERCISE</h2></div><button data-program-picker-close>×</button></header><input class="program-picker__search" type="search" placeholder="Search exercises" autocomplete="off"><div class="program-picker__results"><div class="programedit-empty">Loading exercise library…</div></div></div>';document.body.appendChild(m);document.body.classList.add('program-picker-open');syncMahfittOverlayOwnership();var input=m.querySelector('.program-picker__search'),results=m.querySelector('.program-picker__results'),timer=0,request=0;function load(){var mine=++request;results.innerHTML='<div class="programedit-empty">Searching…</div>';post({action:'exerciseLibrary',q:input.value.trim(),limit:80,offset:0}).then(function(r){if(mine!==request)return;var rows=r.data&&r.data.exercises||[];if(programTypeOf(PROGRAM_DRAFT)==='outdoor')rows=rows.filter(outdoorExerciseCompatible);results.innerHTML=rows.length?rows.map(function(ex,i){return'<button class="program-picker__exercise" data-program-ex="'+i+'"><span><b>'+h(ex.name)+'</b><small>'+h(exerciseLibraryMeta(ex))+'</small></span><em>ADD</em></button>'}).join(''):'<div class="programedit-empty">No matching exercises.</div>';results._rows=rows})}load();input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(load,160)});m.addEventListener('click',function(e){if(e.target.closest('[data-program-picker-close]')){closeProgramExercisePicker();return}var b=e.target.closest('[data-program-ex]');if(!b)return;var ex=results._rows&&results._rows[+b.dataset.programEx];if(!ex)return;PROGRAM_DRAFT.days[dayIndex].items.push(memberProgramExercise(ex));closeProgramExercisePicker();renderProgramEditor();myToast('Exercise added.')});setTimeout(function(){input.focus()},40)}
function saveProgramDraft(){if(PROGRAM_BUSY||!PROGRAM_DRAFT)return;var p=PROGRAM_DRAFT,name=String(p.name||'').trim();if(!name){myToast('Give the program a name first.');return}PROGRAM_BUSY=true;var action=p.dbId?'memberProgramUpdate':'memberProgramCreate',handoff=PROTOCOL_PROGRAM_HANDOFF&&PROTOCOL_PROGRAM_HANDOFF.active?PROTOCOL_PROGRAM_HANDOFF:null;post({action:action,id:p.dbId||'',expectedUpdatedAt:p._updatedAt||handoff&&handoff.programRevision||'',name:name,sub:String(p.sub||'').trim(),body:p}).then(function(r){if(!r.data||!r.data.ok){var er=new Error(r.data&&r.data.error||'Program could not be saved.');er.code=r.data&&r.data.code||'';throw er}var saved=r.data.program||{},savedId=String(saved.id||p.dbId||'');var revision=saved.updated_at||saved.updatedAt||'';if(handoff&&savedId){if(!MAH_PROTOCOL.draft&&handoff.draft)MAH_PROTOCOL.draft=handoff.draft;if(MAH_PROTOCOL.draft){MAH_PROTOCOL.draft.linkedProgramId=savedId;MAH_PROTOCOL.draft.programRevision=revision}handoff.linkedProgramId=savedId;handoff.programRevision=revision}return refreshMemberPrograms().then(function(){return{savedId:savedId,revision:revision,handoff:handoff}})}).then(function(ctx){PROGRAM_DRAFT=null;PROGRAM_BUSY=false;if(ctx.handoff){PROTOCOL_PROGRAM_HANDOFF=null;MAH_PROTOCOL.phase='draft';MAH_PROTOCOL.saveError='';S.view='protocol';protocolPage();myToast('Program saved and linked to this Protocol. Review, then Save Protocol.')}else{programLibrary();myToast('Program saved.')}}).catch(function(e){PROGRAM_BUSY=false;if(e&&e.code==='PROGRAM_CONFLICT')myToast('This Program changed somewhere else. Reload it before saving.');else myToast(e.message||'Program could not be saved.')})}
function deleteProgramDraft(){if(PROGRAM_BUSY||!PROGRAM_DRAFT||!PROGRAM_DRAFT.dbId)return;if(!window.confirm('Remove this program from your library?'))return;PROGRAM_BUSY=true;post({action:'memberProgramArchive',id:PROGRAM_DRAFT.dbId}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Program could not be removed.');return refreshMemberPrograms()}).then(function(){PROGRAM_DRAFT=null;PROGRAM_BUSY=false;programLibrary();myToast('Program removed.')}).catch(function(e){PROGRAM_BUSY=false;myToast(e.message||'Program could not be removed.')})}
function resolvePresetExercise(name){return post({action:'exerciseLibrary',q:name,limit:8,offset:0}).then(function(r){var rows=r.data&&r.data.exercises||[],low=String(name).toLowerCase();return rows.find(function(ex){return String(ex.name||'').toLowerCase()===low})||rows[0]||null})}
function addMemberPreset(id){if(PROGRAM_BUSY)return;var preset=memberPreset(id);if(!preset)return;PROGRAM_BUSY=true;loading('PROGRAM LIBRARY','Building '+preset.name+'…');var names=[];preset.days.forEach(function(day){day[1].forEach(function(n){if(names.indexOf(n)<0)names.push(n)})});Promise.all(names.map(function(n){return resolvePresetExercise(n).then(function(ex){return[n,ex]})})).then(function(pairs){var by={};pairs.forEach(function(x){if(x[1])by[x[0]]=x[1]});var missing=0,body={name:preset.name,sub:preset.sub,days:preset.days.map(function(day){return{name:day[0],items:day[1].map(function(n){var ex=by[n];if(!ex){missing++;return null}var it=memberExerciseFromLibrary(ex,'main');it.target=clone(preset.target);it.sets=[];for(var i=0;i<preset.sets;i++)it.sets.push(blankProgramSet(it.vars));return it}).filter(Boolean)}})};return post({action:'memberProgramCreate',name:preset.name,sub:preset.sub,body:body}).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Program could not be added.');return refreshMemberPrograms().then(function(){return missing})})}).then(function(missing){PROGRAM_BUSY=false;programLibrary();myToast(missing?'Program added · '+missing+' unavailable exercise'+(missing===1?'':'s')+' skipped.':'Program added to My Gym.')}).catch(function(e){PROGRAM_BUSY=false;programLibrary();myToast(e.message||'Program could not be added.')})}

