function openMemberCheckIn(){if(checkInBusy)return;checkInBusy=true;var seq=++checkInSeq;post({action:'checkInCode'}).then(function(r){if(seq!==checkInSeq)return null;if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'Your check-in code could not load.');if(!window.FOBQRCode||!window.FOBQRCode.svg)throw new Error('Your check-in code is still loading. Try once more.');checkInBaseline=String(r.data.lastCheckInId||'');var old=document.getElementById('memberCheckIn');if(old)old.remove();var m=document.createElement('section');m.id='memberCheckIn';m.className='member-checkin';m.innerHTML='<button class="member-checkin__back" data-checkin-close aria-label="Close check-in code"></button><div class="member-checkin__card" role="dialog" aria-modal="true" aria-label="Your MAHFITT check-in code"><button class="member-checkin__x" data-checkin-close aria-label="Close">×</button><div class="member-checkin__qr">'+window.FOBQRCode.svg(r.data.payload,{size:320,margin:3,dark:'#0E1114',light:'#F7F3EC'})+'</div></div>';document.body.appendChild(m);document.body.classList.add('member-checkin-open');syncMahfittOverlayOwnership();m.addEventListener('click',function(e){if(e.target.closest('[data-checkin-close]')){e.preventDefault();e.stopPropagation();closeMemberCheckIn()}});pollMemberCheckIn()}).catch(function(e){if(seq!==checkInSeq)return;checkInBusy=false;myToast(e.message||'Your check-in code could not load.')})}

