function insertSectionExercise(ex,section){if(!ex||!canAddSection(section))return false;
  var it=memberExerciseFromLibrary(ex,section);S.items.push(it);var rawIndex=S.items.length-1;
  exIndex=Math.max(0,exOrder().indexOf(rawIndex));S.exIndex=exIndex;return it}
