function groups(){var rows=(S.progress&&S.progress.sets)||[],nameIds={};rows.forEach(function(x){var n=String(x.exercise_name||'').trim().toLowerCase().replace(/\s+/g,' ');if(!n||!x.exercise_id)return;(nameIds[n]=nameIds[n]||{})[String(x.exercise_id).toLowerCase()]=1});var by={};rows.forEach(function(x){var n=String(x.exercise_name||'').trim().toLowerCase().replace(/\s+/g,' '),ids=nameIds[n]||{},known=Object.keys(ids),key=known.length===1?known[0]:(x.exercise_id||('n:'+n));if(!by[key])by[key]={key:key,name:x.exercise_name||'Exercise',rows:[]};by[key].rows.push(x)});return Object.keys(by).map(function(k){return by[k]}).sort(function(a,b){return a.name.localeCompare(b.name)})}
