function mahMediaPage(){S.view='mah-media';var photos=mahMediaSorted(MAH_MEDIA.items.filter(function(x){return x.kind==='photo'})),videos=mahMediaSorted(MAH_MEDIA.items.filter(function(x){return x.kind==='video'})),split=mahMediaSplitValue();var html=mahfittBannerHTML('MAH MEDIA','progress','home','Back to MAH GYM','hd--progress hd--mah-media')+mahfittPageContextHTML('MAH MEDIA','mah-media-page-context')+'<main class="home mah-media-view" data-mah-media data-video-collapsed="'+(split>=.915?'1':'0')+'"><div class="backbar"><button class="back" data-a="progress">Progress</button><span class="backbar__t">MAH Media</span></div><section class="mah-media-intro"><span>BODY-COMPOSITION JOURNAL</span><h1>MAH MEDIA</h1><p>Photos and short videos form one private chronological record. Scroll downward to watch your progress accumulate over time.</p></section>'+(MAH_MEDIA.error?'<div class="mah-media-error">'+h(MAH_MEDIA.error)+'</div>':'')+'<section class="mah-media-split" aria-label="Progress photos and videos"><section class="mah-media-pane mah-media-photos"><header><span>PHOTOS</span><button data-a="mah-media-add" data-kind="photo" '+(MAH_MEDIA.busy?'disabled':'')+'>＋ ADD PHOTO</button></header><div class="mah-media-timeline">'+(photos.length?photos.map(mahMediaPhotoHTML).join(''):mahMediaEmptyHTML('photo'))+'</div></section><div class="mah-media-divider" data-mah-media-divider role="separator" tabindex="0" aria-label="Resize Photos and Videos" aria-orientation="vertical" aria-valuemin="36" aria-valuemax="94" aria-valuenow="'+Math.round(split*100)+'"><i aria-hidden="true"></i><button data-a="mah-media-restore-videos" aria-label="Restore Videos pane">‹</button></div><section class="mah-media-pane mah-media-videos"><header><span>VIDEOS</span><button data-a="mah-media-add" data-kind="video" '+(MAH_MEDIA.busy?'disabled':'')+'>＋ ADD VIDEO</button></header><div class="mah-media-timeline">'+(videos.length?videos.map(mahMediaVideoHTML).join(''):mahMediaEmptyHTML('video'))+'</div></section></section>'+(MAH_MEDIA.hasMore?'<button class="mah-media-more" data-a="mah-media-more" '+(MAH_MEDIA.busy?'disabled':'')+'>LOAD MORE OF YOUR TIMELINE</button>':'')+'<p class="mah-media-privacy">PRIVATE BODY-PROGRESS MEDIA · ORIGINAL FILES ARE PRESERVED · REFRAME CHANGES PRESENTATION ONLY</p></main>';root.innerHTML=html;mahMediaApplySplit(split,false);bindTempoControl();paintTempoControl();mahMediaBindDivider();mahMediaBindVisibility()}
function mahMediaLoad(append){if(MAH_MEDIA.busy)return;S.view='mah-media';MAH_MEDIA.error='';if(!append&&MAH_MEDIA.loaded){MAH_MEDIA.busy=false;mahMediaPage();return}MAH_MEDIA.busy=true;if(!append&&!MAH_MEDIA.loaded){MAH_MEDIA.items=[];MAH_MEDIA.offset=0;MAH_MEDIA.hasMore=false}if(append)mahMediaPage();var controller=typeof AbortController!=='undefined'?new AbortController():null,timer=controller?setTimeout(function(){try{controller.abort()}catch(e){}},30000):0;MAH_MEDIA.request=controller;post({action:'mahMediaList',offset:append?MAH_MEDIA.offset:0,limit:24},controller?{signal:controller.signal}:null).then(function(r){if(!r.data||!r.data.ok)throw new Error(r.data&&r.data.error||'MAH MEDIA could not load.');var incoming=Array.isArray(r.data.items)?r.data.items:[];if(append){var known=new Set(MAH_MEDIA.items.map(function(x){return String(x.id)}));incoming.forEach(function(x){if(!known.has(String(x.id)))MAH_MEDIA.items.push(x)})}else MAH_MEDIA.items=incoming;MAH_MEDIA.offset=Math.max(0,Number(r.data.nextOffset)||MAH_MEDIA.items.length);MAH_MEDIA.hasMore=!!r.data.hasMore;MAH_MEDIA.loaded=true}).catch(function(error){MAH_MEDIA.error=error&&error.message||'MAH MEDIA could not load.'}).finally(function(){if(timer)clearTimeout(timer);if(MAH_MEDIA.request===controller)MAH_MEDIA.request=null;MAH_MEDIA.busy=false;if(S.view==='mah-media')mahMediaPage()})}
function mahMediaBindVisibility(){if(MAH_MEDIA.observer){try{MAH_MEDIA.observer.disconnect()}catch(e){}MAH_MEDIA.observer=null}var videos=root.querySelectorAll('[data-mah-media-video]');if(!videos.length)return;if(!('IntersectionObserver'in window)){videos.forEach(function(v){var src=v.dataset.src||'';if(src)v.src=src});return}MAH_MEDIA.observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){var v=entry.target,src=v.dataset.src||'';if(entry.isIntersecting&&entry.intersectionRatio>.18){if(src&&!v.getAttribute('src')){v.src=src;try{v.load()}catch(e){}}}else{try{v.pause()}catch(e){}if(v.getAttribute('src')){v.removeAttribute('src');try{v.load()}catch(e){}}}})},{root:null,rootMargin:'180px 0px',threshold:[0,.18]});videos.forEach(function(v){MAH_MEDIA.observer.observe(v)})}
