function mahMediaReadVideoDuration(file){return new Promise(function(resolve,reject){var url=URL.createObjectURL(file),v=document.createElement('video'),done=false;function finish(ok){if(done)return;done=true;if(ok&&Number.isFinite(Number(v.duration))&&Number(v.duration)>0)resolve({duration:Number(v.duration),url:url});else{try{URL.revokeObjectURL(url)}catch(e){}reject(new Error('metadata'))}}v.preload='metadata';v.muted=true;v.playsInline=true;v.onloadedmetadata=function(){var duration=Number(v.duration);try{v.removeAttribute('src');v.load()}catch(e){}if(Number.isFinite(duration)&&duration>0){if(done)return;done=true;resolve({duration:duration,url:url})}else finish(false)};v.onerror=function(){finish(false)};v.src=url})}
