      if(!play.data||!play.data.ok||!play.data.signedUrl)throw new Error('playback');
      it.media=play.data.signedUrl;it.mediaPath=ticket.path;it.mediaScope='member';it.mediaOwner=S.member&&S.member.id||'';it.poster=null;delete it.posterPath;
      it.mediaStart=Math.max(0,+start||0);it.mediaEnd=end==null?null:Math.max(it.mediaStart,+end||0);changed();openMedia(ii);myToast('Private reference video ready.');return true
