/* R51 — MAHFITT AI job dispatch + Settings toggles. Bound once on document so
   a re-render never stacks duplicate listeners (one gesture, one result). */
document.addEventListener('click',function(e){
  var c=e.target&&e.target.closest&&e.target.closest('[data-mahai]');
  if(c){
    e.preventDefault();e.stopPropagation();var act=c.dataset.mahai;
    if(act==='confirm-cancel'){closeMahfittAiConfirm();return}
    if(act==='confirm-ok'){var run=MAHFITT_AI.pending&&MAHFITT_AI.pending.run;closeMahfittAiConfirm();if(typeof run==='function')run();return}
    if(act==='history-toggle'){fabiToggleHistory();return}
    if(act==='history-clear'){fabiRequestClearHistory();return}
    if(act==='history-select'){fabiSelectTurn(c.dataset.turn,true);return}
    if(act==='send'){var input=root.querySelector('[data-mahai-input]');mahfittAiSubmit(input&&input.value||MAHFITT_AI.draft,false);return}
    if(act==='retry'){mahfittAiSubmit(MAHFITT_AI.lastQuestion||MAHFITT_AI.draft,true);return}
    if(act==='job'){mahfittAiActivateJob(c.dataset.job);return}
    return;
  }
  var t=e.target&&e.target.closest&&e.target.closest('[data-mahset]');
  if(t&&t.tagName==='INPUT'){
    var key=t.dataset.mahset,cur=readMahfittSettings();
    if(key==='tutorial')cur.tutorial=!!t.checked;
    else if(key==='smartRecommendation')cur.smartRecommendation=!!t.checked;
    else if(key.indexOf('notif-')===0)cur.notifications[key.slice(6)]=!!t.checked;
    writeMahfittSettings(cur);
    if(key==='notif-master')settingsPage();
  }
},true);
