/* Job III overlay-crown delegation. Meal Log and Scanner mount at body level,
   outside #mygym, so the root listener above cannot receive their shared
   data-a controls. Delegate only ordinary member crowns outside #mygym. This
   keeps one action path without double-firing the in-root crowns or Studio. */
document.addEventListener('click',function(e){
  var b=e.target&&e.target.closest&&e.target.closest('.mf-banner--member [data-a]');if(!b)return;
  if(root&&root.contains(b))return;
  var crown=b.closest('.mf-banner--member');if(!crown||crown.classList.contains('mf-banner--workout'))return;
  var a=b.dataset.a;
  if(['theme','theme-edit','music-studio','music-studio-play','crown-message','mahfitt-ai','calendar','replay-current','banner-collapse','home'].indexOf(a)<0)return;
  e.preventDefault();e.stopPropagation();
  if(a==='theme'){toggleThemeAudio();return}
  if(a==='theme-edit'){openThemeEditor();return}
  if(a==='music-studio'){openMusicStudio();return}
  if(a==='music-studio-play'){toggleStudioQuickPlayback();return}
  if(a==='crown-message'){openCrownMessage();return}
  if(a==='mahfitt-ai'){mahfittNavigate(MAHFITT_AI_ROUTE);return}
  if(a==='calendar'){mahfittNavigate('calendar');return}
  if(a==='replay-current'){replayCurrent();return}
  if(a==='banner-collapse'){toggleBannerMediaCollapsed(crown);return}
  if(a==='home'){mahfittNavigate('home')}
});

/* v402 background checkpoint: commit every in-flight control gesture and save
   the member's state WITHOUT pausing either music owner. The old hard shutdown
   still exists below for a genuine unload/logout. Home, Lock and app-switch are
   no longer misclassified as destruction. */
function checkpointAudioForBackground(){
  if(tempoDragging&&tempoDragInput){setActivePlaybackRate(tempoRateFromRaw(tempoPendingRaw),true);tempoLastCommitRaw=tempoPendingRaw}tempoDragging=false;tempoDragInput=null;
  if(studioRateDragging&&studioRateDragInput)settleStudioRateInput(studioRateDragInput);
  if(studioPitchDragging||studioPitchRaf)settleStudioPitchInput(studioPitchInput);
  flushMusicTrackSettings();persistMusicPreference(true);if(S.session)saveLocal();syncMahfittMediaSession(true);
}
function settleMasterVolumeGesture(){if(!masterVolumeDragging||!masterVolumeInput)return false;masterVolumeLastCommit=setMasterVolumePercent(masterVolumeInput.value,true,true);masterVolumeDragging=false;masterVolumeInput=null;return true}
function settleSongSeekGesture(){if(songSeekDragging&&songSeekInput)return settleSongSeek(songSeekInput);if(songSeekTimer){songSeekOwner=songSeekOwner||controlPlaybackOwner();songSeekDuration=songSeekDuration||ownerPlaybackDuration(songSeekOwner);if(songSeekDuration)return applySongSeekPending(true);cancelSongSeekTimer()}return false}
/* Hard shutdown is intentionally retained for a REAL document teardown. It is
   not attached to ordinary background visibility anymore. */
function suspendAudioForLifecycle(){
  if(lifecycleAudioPaused)return;stopBackgroundMirror('',true);if(tempoDragging&&tempoDragInput){setActivePlaybackRate(tempoRateFromRaw(tempoPendingRaw),true);tempoLastCommitRaw=tempoPendingRaw}tempoDragging=false;tempoDragInput=null;if(studioRateDragging&&studioRateDragInput)settleStudioRateInput(studioRateDragInput);if(studioPitchDragging||studioPitchRaf)settleStudioPitchInput(studioPitchInput);flushMusicTrackSettings();persistMusicPreference(true);lifecycleAudioPaused=true;studioRestoreWanted=false;themeRestoreWanted=false;
  playbackClaimToken++;playbackClaimOwner='';themeWanted=false;studioWanted=false;youtubePendingPlay=false;tiktokPendingPlay=false;
  if(nativeRateTimer){clearTimeout(nativeRateTimer);nativeRateTimer=0}if(ytRateTimer){clearTimeout(ytRateTimer);ytRateTimer=0}cancelStudioTransportTimers();cancelReversePrewarm();resetStudioPitchProcessor();
  if(themeReverbCutTimer){clearTimeout(themeReverbCutTimer);themeReverbCutTimer=0}if(audioGraphBuilt&&!musicReverb)setThemeReverbWired(false);
  stopThemeAudio(true);if(musicReverseActive)pauseReversePlayback();try{studioAudio.pause()}catch(e){}studioPlaying=false;
  try{if(audioCtx&&audioCtx.state==='running')audioCtx.suspend()}catch(e){}try{if(studioCtx&&studioCtx.state==='running')studioCtx.suspend()}catch(e){}
  paintPlaybackButtons();paintTempoControl();syncMusicMotion();
}
