/* iOS Home Screen apps can be frozen and later resumed without a full page
   reload. Keep the healthy in-memory UI untouched; only repair stale shell
   state that would otherwise leave a blank/non-interactive surface. */
var lastSwUpdateCheck=0;
function restoreCanonicalPitchAfterLifecycle(){
  /* Background/freeze can suspend Web Audio and iOS can restore an element at a
     decoder rate that no longer matches the UI. Re-read the one persisted member
     Pitch value, repaint every surface, then reapply it to the CURRENT owner only.
     No source is restarted, sought or duplicated. */
  /* Never let an older persisted value steal an in-flight physical gesture. */
  if(studioPitchDragging&&studioPitchInput)return cleanPitchSemitones(studioPitchPending);
  /* R26: the live in-memory axis is canonical. A focus/pageshow event must never
     resurrect an older localStorage value over a Pitch the member already set
     in this song. A true reload/song boundary already establishes 0ST. */
  var live=cleanPitchSemitones(studioPitch);if(typeof PITCH_FEATURE_ENABLED!=='undefined'&&!PITCH_FEATURE_ENABLED)live=0;studioPitch=live;studioPitchPending=live;studioPitchLastCommit=live;syncStudioPitchSurfaces(live);cancelPitchDecoderTimers();
  var owner=activePlaybackOwner();
  if(owner==='theme'&&activeMusicProvider()==='native')applyNativeRate(musicRate,true);
  if(owner==='studio'&&musicCurrentTrack){applyStudioRate(studioRate,true);if(typeof syncStudioPitchRouting==='function')syncStudioPitchRouting(true);if(studioGraphBuilt)applyStudioGainSafety()}
  return live
}
function foregroundHealth(){
  if(document.hidden)return;
  refreshHealthAfterReturn();
  if(document.body.classList.contains('theme-editor-open')&&!document.getElementById('mygymThemeEditor'))document.body.classList.remove('theme-editor-open');
  syncMahfittOverlayOwnership();
  if(S.theme)applyTheme(S.theme);
  restoreCanonicalPitchAfterLifecycle();
  /* Returning from the background must not lose the transport settings. iOS
     suspends the AudioContext, so it is resumed rather than rebuilt. */
  if(activePlaybackOwner()==='studio'&&(studioPlaying||studioWanted)){applyStudioRate(studioRate,true);if(studioAudioRouted())resumeStudioContext();if(studioGraphBuilt){if(typeof syncStudioPitchRouting==='function')syncStudioPitchRouting(true);applyStudioEq();applyStudioReverb();applyStudioGainSafety()}}
  else if(activePlaybackOwner()==='theme'&&(themePlaying||themeWanted)){restoreNativeRate();if(themeAudioRouted())resumeAudioContext();if(audioGraphBuilt){applyMusicEq();applyReverbMix()}}paintTempoControl();
  /* elapsed() is wall-clock based so the VALUE was always right, but nothing
     repainted it on return and nothing re-established the interval if iOS had
     dropped it. startTick clears before setting, so this cannot duplicate. */
  if(S.session&&S.running){
    var tmEl=document.getElementById('tm');
    if(tmEl){tmEl.textContent=clock(elapsed());startTick()}
  }
  paintSaveState();
  if(root&&!root.firstElementChild&&!bootPending)boot();
  var now=Date.now();
  if('serviceWorker'in navigator&&!activePlaybackOwner()&&!S.session&&now-lastSwUpdateCheck>300000){
    lastSwUpdateCheck=now;
    navigator.serviceWorker.getRegistration('/').then(function(reg){if(reg)reg.update().catch(function(){})}).catch(function(){});
  }
}
